\emph{(Conjecture~\ref{conj:DL0})}\label{conj:intro:higgs}
    Let $C$ be a smooth projective curve, $G$ a reductive group and $^{L}G$ its Langlands dual. 
    Let $\mathrm{Higgs}_G$ be the derived moduli stack of $G$-Higgs bundles. 
    For $(\chi, w) \in \pi_1(G) \times Z(G)^{\vee}$, there is an equivalence
    \begin{align}\label{intro:cohL}
        \operatorname{IndCoh}(\mathrm{Higgs}_{^{L}G}(w)^{\mathrm{ss}})_{-\chi}\simeq \operatorname{IndL}(\mathrm{Higgs}_{G}(\chi))_w.
    \end{align}

Consider the quasi-compact open substack of semistable $G$-Higgs bundles 
\begin{align*}
    \mathrm{Higgs}_G(\chi)^{\mathrm{ss}} \subset \mathrm{Higgs}_G(\chi). 
\end{align*}

\emph{(Theorem~\ref{thm:mainLG})}\label{conj:intro}
There exist subcategories (which we refer to as quasi-BPS categories)
\begin{align}\label{intro:qbps0}
    \mathbb{T}_G(\chi)_w \subset \operatorname{Coh}(\mathrm{Higgs}_G(\chi)^{\mathrm{ss}})_w
\end{align}
such that there is a semiorthogonal decomposition 
\begin{align}\label{intro:sod:L}
    \operatorname{L}(\mathrm{Higgs}_G(\chi))_w=\left\langle \mathbb{T}_{M}(\chi_{M})_{w_{M}} : \begin{array}{ll}
     \mu_M(\chi_{M})\in N(T)_{\mathbb{Q}+}^{W_M} \\ \mu_M(w_M)=\mu_G(w) \end{array}\right\rangle.
\end{align}
    Here, the right-hand side is after all standard parabolic subgroups $P\subset G$ with Levi 
    quotient $M$, 
    satisfying
    \begin{align}\label{intro:chiw}
    (\chi_{M}, w_{M}) \in \pi_1(M) \times Z(M)^{\vee}, \mathbb{}a_{M}(\chi_{M}, w_{M})=(\chi, w).
    \end{align}

\label{conj:Higgs}
There is an equivalence 
\begin{align}\label{intro:eq:CohL}
    \operatorname{Coh}(\mathrm{Higgs}_{^{L}G}(w)^{\mathrm{ss}})_{-\chi} \simeq \operatorname{L}(\mathrm{Higgs}_{G}(\chi))_{w}
\end{align}
under which the semiorthogonal decompositions (\ref{sod:intro1}) and (\ref{sod:intro2}) into quasi-BPS categories are 
compatible.

\label{intro:corK}
If $G \in \{\operatorname{GL}_r, \mathrm{PGL}_r, \mathrm{SL}_r\}$,  
there is an isomorphism of rational topological K-theories respecting the filtration induced by the semiorthogonal decompositions~(\ref{sod:intro1}) and (\ref{sod:intro2}): 
\begin{align*}
    K^{\mathrm{top}}(\operatorname{Coh}(\mathrm{Higgs}_{^{L}G}(w)^{\mathrm{ss}})_{-\chi})_{\mathbb{Q}} \cong K^{\mathrm{top}}(\operatorname{L}(\mathrm{Higgs}_{G}(\chi))_w)_{\mathbb{Q}}
\end{align*}
in the following cases: 
(i) $g(C)=0$; (ii) $r=2$; (iii) $(r, w)$ are coprime. 

In the case of (i) $g(C)=0$, the above isomorphism holds with integral coefficients, 
and also holds for algebraic K-theory.

\label{intro:conj:qbps}
For $(\chi, w)\in \pi_1(G)\times Z(G)^{\vee}$, there is an equivalence 
\begin{align}\label{intro:equiv:T}
    \mathbb{T}_{^{L}G}(w)_{-\chi} \simeq \mathbb{T}_{G}(\chi)_{w}.
\end{align}

\begin{align*}
\xymatrix{
\mbox{Donaldson-Thomas theory } \ar[rrr]^-{{\mbox{\tiny{categorification}}}} & & &\mbox{Categorical DT theory} \ar@<1ex>[d]^-{{\mbox{\tiny{formulation}}}} \\
\mbox{Geometric Langlands } \ar[rrr]_-{{\mbox{\tiny{classical limit}}}} & & &\mbox{Dolbeault Langlands} \ar@<1ex>[u]^-{{\mbox{\tiny{symmetry}}}}
}  
\end{align*}

It is well-known that it admits a degeneration 
to the dg-category of coherent sheaves of the cotangent space $\Omega_X$
\begin{align*}
    \text{D-mod}_{\mathrm{coh}}(X) \leadsto \operatorname{Coh}(\Omega_X). 
\end{align*}

The results of our construction of limit categories are summarized as follows: 
\begin{propdef}\emph{(Definition~\ref{def:Lcat}, Lemma~\ref{lem:emb})}\label{intro:propdef}
For a pair $(\mathfrak{M}, \delta)$ of a quasi-smooth QCA derived stack $\mathfrak{M}$
with $\mathbb{L}_{\mathfrak{M}}\simeq \mathbb{T}_{\mathfrak{M}}$ and $\delta \in \mathrm{Pic}(\mathfrak{M})_{\mathbb{R}}$, 
there exists a subcategory 
\begin{align*}
     \operatorname{L}(\mathfrak{M})_{\delta} \subset \operatorname{Coh}(\mathfrak{M})
\end{align*}
    satisfying the following.

\emph{(Definition~\ref{def:Lcat}, Lemma~\ref{lem:emb})}\label{intro:propdef}
For a pair $(\mathfrak{M}, \delta)$ of a quasi-smooth QCA derived stack $\mathfrak{M}$
with $\mathbb{L}_{\mathfrak{M}}\simeq \mathbb{T}_{\mathfrak{M}}$ and $\delta \in \mathrm{Pic}(\mathfrak{M})_{\mathbb{R}}$, 
there exists a subcategory 
\begin{align*}
     \operatorname{L}(\mathfrak{M})_{\delta} \subset \operatorname{Coh}(\mathfrak{M})
\end{align*}
    satisfying the following. Suppose that there is a diagram 
   \begin{align*}
\xymatrix{
& \mathcal{V} \ar[d] \\
\mathfrak{M}\simeq s^{-1}(0) \ar@<-0.3ex>@{^{(}->}[r]^-{i} & \mathcal{Y} \ar@/_18pt/[u]_-{s}
}
\end{align*}
where $\mathcal{Y}$ is a smooth stack, $\mathcal{V} \to \mathcal{Y}$ is a vector bundle 
with a section $s$, and 
$s^{-1}(0)$ is the derived zero locus of $s$. Then 
an object $\mathcal{E} \in \operatorname{Coh}(\mathfrak{M})$ lies in 
$\operatorname{L}(\mathfrak{M})_{\delta}$ if and only if, for any field extension $k'/k$ and 
map $\nu \colon (B\mathbb{G}_m)_{k'} \to \mathfrak{M}$, we have 
\begin{align}\notag
    \mathrm{wt}(\nu^{\ast}i^{\ast}i_{\ast}\mathcal{E})
    \subset \left[\frac{1}{2} c_1 (\nu^{\ast}\mathbb{L}_{\mathcal{V}}^{<0}), 
    \frac{1}{2} c_1 (\nu^{\ast}\mathbb{L}_{\mathcal{V}}^{>0})
    \right]+c_1(\nu^{\ast}\delta). 
\end{align} 
Here, $\nu^* \mathbb{L}_{\mathcal{V}}^{>0}$ (resp.~$\nu^* \mathbb{L}_{\mathcal{V}}^{<0}$)
is the sum of positive (resp.~negative) $\mathbb{G}_m$-weights, see Subsection~\ref{subsec:Gmwt}. Further for $\mathcal{F}\in\mathrm{Coh}(B\mathbb{G}_m)$, the set $\mathrm{wt}(\mathcal{F}) \subset \mathbb{Z}$ is defined to be 
$w\in \mathbb{Z}$ with $\mathcal{F}_w \neq 0$, where $\mathcal{F}_w$ is the direct summand of $\mathcal{F}$ with $\mathbb{G}_m$-weight $w$. 

For a general (not necessarily quasi-compact) quasi-smooth derived stack 
$\mathfrak{M}$ with $\mathbb{L}_{\mathfrak{M}}\simeq \mathbb{T}_{\mathfrak{M}}$, we define 
\begin{align*}
    \operatorname{IndL}(\mathfrak{M})_{\delta}:=\lim_{\mathcal{U}\subset \mathfrak{M}} \operatorname{Ind}(\operatorname{L}(\mathcal{U})_{\delta})
\end{align*}
where the limit is after all the QCA open substacks $\mathcal{U}\subset \mathfrak{M}$, and define 
\begin{align*}
    \operatorname{L}(\mathfrak{M})_{\delta} \subset \operatorname{IndL}(\mathfrak{M})_{\delta}
\end{align*}
to be the subcategory of compact objects. 
For a smooth stack $\mathcal{X}$, we 
call $\operatorname{L}(\Omega_{\mathcal{X}})_{\delta}$ the limit category.

\emph{(Conjecture~\ref{conj:L})}\label{conj:L2}
    For any $\mathcal{E}\in \mathrm{D}\text{-}\mathrm{mod}_{\mathrm{coh}}(\mathcal{X})$, there is a good filtration on 
    it whose associated graded lies in $\operatorname{L}(\Omega_{\mathcal{X}})_{\frac{1}{2}}$.

\emph{(Proposition~\ref{prop:pback}, Theorem~\ref{thm:proj})}\label{intro:thmfunct}
For a morphism $f\colon \mathcal{X} \to \mathcal{Y}$ of smooth QCA stacks
and the associated Lagrangian correspondence
\begin{align}\label{intro:lag}
\Omega_{\mathcal{X}} \stackrel{\beta}{\leftarrow} f^{*}\Omega_{\mathcal{Y}} \stackrel{\alpha}{\to} \Omega_{\mathcal{Y}}
\end{align}
we have the following: 
\begin{enumerate}
    \item If $f$ is smooth, the Lagrangian correspondence (\ref{intro:lag})
induces the functor 
\begin{align}\label{intro:pback}
    f^{\Omega!}=\beta_{*}\alpha^! \colon \operatorname{L}(\Omega_{\mathcal{Y}})_{\delta \otimes \omega_{\mathcal{Y}}^{1/2}}
    \to \operatorname{L}(\Omega_{\mathcal{X}})_{f^*\delta \otimes \omega_{\mathcal{X}}^{1/2}}.
\end{align}
\item If $f$ is projective, the Lagrangian 
correspondence (\ref{intro:lag}) induces the functor
\begin{align}\label{intro:push}
    f^{\Omega}_{*}=\alpha_{*}\beta^* \colon \operatorname{L}(\Omega_{\mathcal{X}})_{f^*\delta \otimes \omega_{\mathcal{X}}^{1/2}}
    \to \operatorname{L}(\Omega_{\mathcal{Y}})_{\delta \otimes \omega_{\mathcal{Y}}^{1/2}}.
\end{align}
\end{enumerate}

\label{intro:thm:gen}\emph{(Theorem~\ref{thm:mainLG})}
The dg-category $\operatorname{IndL}(\mathrm{Higgs}_G(\chi))_w$ is compactly generated
by the subcategory of compact objects $\operatorname{L}(\mathrm{Higgs}_G(\chi))_w$.

\label{conj:Higgs2} 
An equivalence (\ref{intro:cohL}) 
restricts to an equivalence:
\begin{align}\label{intro:equiv:ind2} \operatorname{IndCoh}_{\mathcal{N}}(\mathrm{Higgs}_{^{L}G}(w)^{\mathrm{ss}})_{-\chi} \simeq \operatorname{IndL}_{\mathcal{N}}(\mathrm{Higgs}_{G}(\chi))_{w}. 
\end{align}

\label{rmk:conj} 
The nilpotent singular support condition for limit categories is discussed in Subsection~\ref{subsec:ssupport}.
Note that the corresponding condition for D-modules is unconditionally 
satisfied. 



As we will mention in Remark~\ref{rmk:limit2}, an equivalence (\ref{intro:equiv:ind2}) is expected
to be a genuine classical limit of GLC~(\ref{intro:GLC}). 

On the other hand, a version of GLC without the nilpotent singular support condition is briefly discussed in~\cite[Remark~1.6.9]{GLC1}, under the name of the \textit{renormalized} geometric Langlands conjecture:
\begin{align*}
    \operatorname{IndCoh}(\mathrm{Locsys}_{^LG}) \simeq \text{D-mod}(\mathrm{Bun}_G)^{\mathrm{ren}}
\end{align*}
where the compact objects of the right hand side are locally compact D-modules on $\mathrm{Bun}_G$, denoted by 
\begin{align*}
    \text{D-mod}(\mathrm{Bun}_G)^{\rm{lcp}} \subset \text{D-mod}(\mathrm{Bun}_G).
\end{align*}
An equivalence (\ref{intro:cohL}) is regarded as a classical limit of renormalized GLC. 
A proof of the renormalized version is not currently available in the literature.

\emph{(Corollary~\ref{cor:1}, Corollary~\ref{cor:1prime})}\label{intro:cor2}
For a fixed $(r, w)\in \mathbb{Z}^2$, there exist right and left monoidal actions on 
     the following direct sum 
    \begin{align*}
   \mathbb{H} \curvearrowright     \bigoplus_{\chi \in \mathbb{Z}}\operatorname{L}(\mathrm{Higgs}_{\mathrm{GL}_r}
   \mathbb(\chi))_w \curvearrowleft\mathbb{H}.
    \end{align*}

\emph{(Corollary~\ref{cor:1}, Corollary~\ref{cor:1prime})}\label{intro:cor3}
For coprime $(r, w)$, there exist right and left monoidal actions on 
     the following direct sum of BPS categories 
    \begin{align*}
 \mathbb{H} \curvearrowright     \bigoplus_{\chi \in \mathbb{Z}}
 \mathbb{T}_{\operatorname{GL}_r}(\chi)_w \curvearrowleft\mathbb{H}.
    \end{align*}

For a general reductive group $G$, we construct a Hecke functor associated with a minuscule coweight $\mu$:\footnote{As we discuss in Subsection~\ref{subsec:heckeG}, there are still obstructions to define a Hecke functor if $\mu$ is not minuscule, either due to infinite-dimensionality of Hecke correspondences or to singularities of Schubert cycles in the affine Grassmannians.}
\begin{align*}
    H_x^{\mu} \colon \operatorname{L}(\mathrm{Higgs}_G(\chi))_w \to \operatorname{L}(\mathrm{Higgs}_G(\chi+\overline{\mu}))_{w},
\end{align*}
see Subsection~\ref{subsec:heckeG}.

Consider the monoidal category 
  \begin{equation}\label{def:Hall}
  \text{HA}(C):=\bigoplus_{r\in\mathbb{N}} \text{HA}_r(C)
  \end{equation}
  and its corresponding K-theoretic Hall algebra:
  \[\mathrm{KHA}(C):=K^{\text{top}}_\bullet(\mathrm{HA}(C)).\]

Following Grojnowski's observation for quivers, we assume that the following PBW isomorphism of  $\mathbb{N}\times\mathbb{Z}^{\oplus 2}$-graded vector spaces holds, where $z$ has degree $(0,1,0)$ and $q$ has degree $(0,0,1)$:
  \begin{equation}\label{iso:KHAC}
  \mathrm{KHA}(C)_\mathbb{Q}\cong \mathrm{Sym}\left(\bigoplus_{r\in\mathbb{N}}\mathrm{BPS}(r)\otimes\mathbb{Q}[z^{\pm 1}, q^{\pm 1}]\right).
  \end{equation}

\emph{(\cite{TodaGL2, TodaA})}\label{thm:BA}
For $G=\operatorname{GL}_r, \mathrm{SL}_r$ or $\mathrm{PGL}_r$, 
there is a $\mathrm{B}^{A}$-linear equivalence 
\begin{align*}
    \operatorname{IndCoh}_{\mathcal{N}}(\mathrm{Higgs}_{\operatorname{GL}_2}(w)^{\mathrm{ss}}\times_{\mathrm{B}}\mathrm{B}^{A})_{-\chi} \stackrel{\sim}{\to}
    \operatorname{IndL}_{\mathcal{N}}(\mathrm{Higgs}_{\operatorname{GL}_2}(\chi)\times_{\mathrm{B}}\mathrm{B}^{A})_{w}
\end{align*}
which is compatible with Wilson/Hecke operators.

For a stack $\mathcal{X}$, it is defined by 
\begin{align*}
    \operatorname{IndCoh}(\mathcal{X})=\lim_{U\to \mathcal{X}}\operatorname{IndCoh}(U)
\end{align*}
for affine derived schemes $U \to \mathcal{X}$.

A morphism $f$ is called \textit{quasi-smooth} 
if $\mathbb{L}_f$ is perfect of cohomological amplitude $[-1, 1]$, and $\mathcal{X}$ is called 
\textit{quasi-smooth} if $\mathcal{X} \to \operatorname{Spec} k$ is quasi-smooth.

We set $M(T)_{\mathbb{R}}:=M(T)\otimes_{\mathbb{Z}}\mathbb{R}$ etc. 
There is a perfect pairing 
\begin{align*}
    \langle -, - \rangle \colon M(T)_{\mathbb{R}}\times N(T)_{\mathbb{R}} \to \mathbb{R}. 
\end{align*}

\emph{(\cite{I, Hirano, T})}\label{thm:Kduality}
There is an equivalence 
\begin{align}\notag
	\Psi \colon \operatorname{Coh}(\mathfrak{M})\stackrel{\sim}{\to}
	\mathrm{MF}^{\mathrm{gr}}(\mathcal{V}^{\vee}, f) 
	\end{align}
	given by $\Psi(-)=\mathcal{K}\otimes_{\mathcal{O}_{\mathfrak{M}}}(-)$. Here $\mathcal{K}$ is the following Koszul factorization, see~\cite[Theorem~2.3.3]{T}
    \begin{align}\notag
        \mathcal{K}=(\mathcal{O}_{\mathcal{V}^{\vee}}\otimes_{\mathcal{O}_{\mathcal{Y}}}\mathcal{O}_{\mathfrak{M}}, d_{\mathcal{K}}).
    \end{align}

The subcategory $\mathcal{W}$ is an example of a \textit{window subcategory}, and there is an equivalence~\cite{HL}: 
\begin{align*}
    j^* \colon \mathcal{W} \stackrel{\sim}{\to} \operatorname{Coh}(\mathcal{Y}^{\circ}), \ 
    \mathcal{Y}^{\circ}:=\mathcal{Y}\setminus \mathcal{S}. 
\end{align*}

However, if we define the following subcategory slightly larger than $\mathcal{W}$:
\begin{align}\label{sod:LY}
    \operatorname{M}(\mathcal{Y}) \subset \operatorname{Coh}(\mathcal{Y})
\end{align}
generated by $\mathcal{O}_{\mathcal{Y}}(a)$
with $a\in [0, m]$ (i.e. including weights of the left boundary), then 
there is a semiorthogonal decomposition 
\begin{align*}
    \operatorname{M}(\mathcal{Y})=\langle \operatorname{Coh}(\mathcal{Z})_0, \mathcal{W} \rangle. 
\end{align*}

The map (\ref{map:nu}) may not be quasi-smooth, but we can modifiy 
it to a quasi-smooth map in the following way:
\begin{consdef}\emph{(\cite[Construction~3.2.2]{HalpK32})}\label{def:construction}
A map $\nu$ extends to a map 
\begin{align}\label{nu:reg}
\nu^{\mathrm{reg}} \colon \mathfrak{g}_x^{\vee}[-1]/(\mathbb{G}_m)_{k'} \to \mathfrak{M}
\end{align}
called \textit{regularization}.

\emph{(\cite[Construction~3.2.2]{HalpK32})}\label{def:construction}
A map $\nu$ extends to a map 
\begin{align}\label{nu:reg}
\nu^{\mathrm{reg}} \colon \mathfrak{g}_x^{\vee}[-1]/(\mathbb{G}_m)_{k'} \to \mathfrak{M}
\end{align}
called \textit{regularization}. It satisfies that the map 
\begin{align*}
    \mathbb{L}_{\mathfrak{M}}|_{x} \to 
    \mathbb{L}_{\mathfrak{g}_x^{\vee}[-1]}|_{0}=\mathfrak{g}_x[1]
\end{align*}
induces an isomorphism on $\mathcal{H}^{-1}(-)$. 

The regularization map is quasi-smooth, unique up to 2-isomorphism, 
and determined by a choice of splitting of 
$\mathcal{H}^{-1}(\mathbb{L}_{\mathfrak{M}}|_{x})[1] 
\to \mathbb{L}_{\mathfrak{M}}|_{x}$.

\label{def:Lcat}
We define the subcategory 
\begin{align}\label{def:L}
    \mathrm{L}(\mathfrak{M})_{\delta} \subset \operatorname{Coh}(\mathfrak{M})
\end{align}
to be consisting of objects $\mathcal{E}$ 
such that, for any field extension $k'/k$ and a map
$\nu \colon (B\mathbb{G}_m)_{k'} \to \mathfrak{M}$ 
with $\nu(0)=x$ and regularization (\ref{nu:reg}),
we have 
\begin{align}\label{wt:nu}
\mathrm{wt}(\iota_{\ast}\nu^{\mathrm{reg}\ast}(\mathcal{E}))
\subset \left[\frac{1}{2} c_1 (T_x^{<0}),
\frac{1}{2} c_1 (T_x^{>0}) \right]+
\frac{1}{2}c_1(\mathfrak{g}_x)+c_1(\nu^*\delta).
\end{align}

\label{rmk:reg}
The definition of $\operatorname{L}(\mathfrak{M})_{\delta}$ is independent of a choice of a regularization, 
since it is unique up to 2-isomorphisms.

Let $\nu \colon (B\mathbb{G}_m)_{k'}\to \mathfrak{M}$
be a map such that $\nu(0)=x$. 
Let $\mathcal{V}_x$ be the fiber of $\mathcal{V} \to \mathcal{Y}$
at $j(x)$, which is a $G_x=\mathrm{Aut}(x)$-representation. 
Below we regard the $G_x$-representation 
as a $\mathbb{G}_m$-representation 
via the cocharacter 
$(\mathbb{G}_m)_{k'} \to G_x$
induced by $\nu$. 
We have the Cartesian square 
\begin{align*}
\xymatrix{
\mathfrak{M} \ar@<-0.3ex>@{^{(}->}[r]^-{i}\ar@{}[rd]|\square & \mathcal{Y} \\
\mathcal{V}_x[-1]/(\mathbb{G}_m)_{k'}
\ar[u]^-{\widetilde{\nu}} 
\ar[r]^-{\widetilde{\iota}} & (B\mathbb{G}_m)_{k'} \ar[u]_-{j \circ \nu} 
}
\end{align*}

Then we have the isomorphisms
\begin{align}\notag
    \nu^{\ast}i^{\ast}i_{\ast}\mathcal{E} \cong (i\circ \nu)^{*}i_{*}\mathcal{E}\cong \widetilde{\iota}_{\ast}\widetilde{\nu}^{\ast}\mathcal{E}. 
\end{align}
From the distinguished triangle 
\begin{align*}
    \mathcal{V}^{\vee}|_{\mathfrak{M}} \to \mathbb{L}_{\mathcal{Y}}|_{\mathfrak{M}} \to \mathbb{L}_{\mathfrak{M}}
\end{align*}
we have the exact sequence 
of $G_x$-representations
\begin{align}\label{exact:Vx}
    0 \to \mathfrak{g}_x \to \mathcal{V}_x^{\vee}
    \to \mathcal{H}^0(\mathbb{L}_{\mathcal{Y}}|_{x})
    \to T_x \to 0
\end{align}
and $\mathcal{H}^{1}(\mathbb{L}_{\mathcal{Y}}|_{x}) \stackrel{\cong}{\to} \mathfrak{g}_x^{\vee}$. 
The first inclusion in (\ref{exact:Vx}) determines a
morphism 
\begin{align*}
    \eta \colon \mathcal{V}_x[-1]/(\mathbb{G}_m)_{k'} \to \mathfrak{g}_x^{\vee}[-1]/(\mathbb{G}_m)_{k'}.
\end{align*}
We have the commutative diagram 
\begin{align*}
    \xymatrix{
(B\mathbb{G}_m)_{k'} & \mathfrak{g}_x^{\vee}[-1]/(\mathbb{G}_m)_{k'} \ar[r]^-{\nu^{\mathrm{reg}}} \ar[l]_-{\iota} 
& \mathfrak{M} \\
& \mathcal{V}_x[-1]/(\mathbb{G}_m)_{k'}
\ar[lu]^-{\widetilde{\iota}} \ar[ru]_-{\widetilde{\nu}} \ar[u]_-{\eta}&    
    }
\end{align*}
Then we have 
\begin{align*}
    \widetilde{\iota}_{\ast}\widetilde{\nu}^{\ast}\mathcal{E}
\cong \iota_{\ast}\eta_{\ast}\eta^{\ast}\nu^{\mathrm{reg}\ast}\mathcal{E} \cong \iota_{\ast}(\nu^{\mathrm{reg}\ast}\mathcal{E}\otimes 
\eta_{\ast}\mathcal{O}_{\mathcal{V}_x[-1]}).
\end{align*}
We divide the exact sequence (\ref{exact:Vx}) into 
two short exact sequences
\begin{align}\label{exact:gW}
    0 \to \mathfrak{g}_x \to \mathcal{V}_x^{\vee} \to 
    W \to 0, \ 
    0 \to W \to \mathcal{H}^0(\mathbb{L}_{\mathcal{Y}}|_{x})
    \to T_x \to 0. 
\end{align}

Then we have 
\begin{align*}
    \eta_{\ast}\mathcal{O}_{\mathcal{V}_x[-1]}
    \cong \left(\bigwedge^{\bullet}W\right) \otimes 
    \mathcal{O}_{\mathfrak{g}_x^{\vee}[-1]}
\end{align*}
where the complex in the right-hand side has 
zero differentials. 
Therefore 
\begin{align}\notag
    \widetilde{\iota}_{\ast}\widetilde{\nu}^{\ast}\mathcal{E}
    \cong \iota_{\ast}\nu^{\mathrm{reg}\ast}\mathcal{E} \otimes\bigwedge^{\bullet}W.
\end{align}

It follows that 
$\mathrm{wt}(\iota_{\ast}\nu^{\mathrm{reg}\ast}\mathcal{E})$
lies in $[a, b]$ if and only if 
\begin{align*}
\mathrm{wt}(\nu^{\ast}i^{\ast}i_{\ast}\mathcal{E})=
\mathrm{wt}(\widetilde{\iota}_{\ast}\widetilde{\nu}^{\ast}\mathcal{E})
\subset [a+c_1 (W^{<0}), b+c_1 (W^{>0})].
\end{align*}
Using the exact sequences (\ref{exact:gW}), we have 
\begin{align*}
    \frac{1}{2} c_1 (\mathbb{L}_{\mathcal{V}}|_{x}^{>0}) &=\frac{1}{2} c_1(\mathcal{V}_x^{\vee >0})+
    \frac{1}{2}c_1(\mathbb{L}_{\mathcal{Y}}|_{x}^{>0}) \\
    &=\frac{1}{2} c_1(\mathcal{V}_x^{\vee>0})+
    \frac{1}{2}c_1(\mathcal{H}^0(\mathbb{L}_{\mathcal{Y}}|_{x})^{>0})
    -\frac{1}{2} c_1((\mathfrak{g}_x^{\vee})^{>0}) \\
    &=\frac{1}{2}c_1(\mathfrak{g}_x^{>0})+\frac{1}{2}c_1(T_x^{>0})+\frac{1}{2}c_1(\mathfrak{g}_x^{<0})
    +c_1 (W^{>0}) \\
    &=\frac{1}{2}c_1(T_x^{>0})+\frac{1}{2}c_1(\mathfrak{g}_x)+c_1 (W^{>0}). 
\end{align*}
Similarly we have 
\begin{align*}
 \frac{1}{2} c_1 (\mathbb{L}_{\mathcal{V}}|_{x}^{<0})
 =\frac{1}{2}c_1(T_x^{<0})+\frac{1}{2}c_1(\mathfrak{g}_x)+c_1 (W^{<0}).
\end{align*}
Therefore the lemma holds.

\label{lem:duality}
The functor (\ref{dual:M}) restricts to an equivalence 
\begin{align*}
\mathbb{D} \colon \operatorname{L}(\mathfrak{M})_{\delta}^{\mathrm{op}} \stackrel{\sim}{\to} \operatorname{L}(\mathfrak{M})_{\delta^{-1}}. 
\end{align*}

\label{def:sstack}
A smooth stack $\mathcal{Y}$ is called 
\textit{symmetric} 
if we have 
\begin{align*}
	[\mathbb{L}_{\mathcal{Y}}]=[\mathbb{L}_{\mathcal{Y}}^{\vee}] \in K(\mathcal{Y}).
	\end{align*}

\label{exam:quiver}
	Let $G$ be a reductive algebraic group and let $Y$ be a self-dual $G$-representation. 
	Then any open substack of $Y/G$ is symmetric.

We define the following \textit{magic category} as a subcategory of $\operatorname{Coh}(\mathcal{Y})$:
 \begin{defn}                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          \end{defn}
\begin{remark}
In the case of $\mathcal{Y}=Y/G$ for a self-dual representation $Y$ of a reductive group $G$, 
the subcategory (\ref{MY:delta}) is also defined by some explicit generators, 
see Proposition~\ref{prop:QB:weight}.

\label{defn:QBY}
For a smooth symmetric stack $\mathcal{Y}$ and $\delta \in \mathrm{Pic}(\mathcal{Y})_{\mathbb{R}}$, we 
define 
the subcategory 
\begin{align}\label{MY:delta}
\operatorname{M}(\mathcal{Y})_{\delta} \subset \operatorname{Coh}(\mathcal{Y})
\end{align}
to be consisting of objects $\mathcal{E} \in \operatorname{Coh}(\mathcal{Y})$ 
such that, for any field extension $k'/k$ and a
map $\nu \colon (B\mathbb{G}_m)_{k'} \to \mathcal{Y}$, the following holds: 
\begin{align*}
    \mathrm{wt}(\nu^{\ast}\mathcal{E}) \subset 
    \left[-\frac{1}{2}n_{\mathcal{Y}, \nu}, \frac{1}{2}n_{\mathcal{Y}, \nu}   \right]
    +\langle \delta, \nu\rangle. 
\end{align*}
Here, $n_{\mathcal{Y}, \nu}$ is defined by 
\begin{align}\label{def:nV}
	n_{\mathcal{Y}, \nu}:=c_1(\nu^{\ast}\mathbb{L}_{\mathcal{Y}}^{>0})=-c_1(\nu^{\ast}\mathbb{L}_{\mathcal{Y}}^{<0}).
	\end{align}
The second equality follows from the definition of a symmetric stack.

\label{prop:comparemagic}
    The equivalence (\ref{Kdual:magic}) restricts to an equivalence 
    \begin{align*}
        \Psi \colon \operatorname{L}(\mathfrak{M})_{\delta} \stackrel{\sim}{\to} \mathrm{MF}^{\mathrm{gr}}(\operatorname{M}(\mathcal{V}^{\vee})_{\delta \otimes \omega_{\mathcal{Y}}^{1/2}}, f).
    \end{align*}

The proposition follows from the characterization of the category $\operatorname{L}(\mathfrak{M})_{\delta}$ in Lemma~\ref{lem:emb} and the construction 
of Koszul equivalence in Theorem~\ref{thm:Kduality}. See 
the arguments of~\cite[Lemma~4.5]{PT0}, ~\cite[Lemma~2.6]{PTquiver}

Let $\delta \in \mathrm{Pic}(\mathcal{X})_{\mathbb{R}}$, and 
regard it as $\mathbb{R}$-line bundle on $\Omega_{\mathcal{X}}$ 
via pull-back of the projection 
\begin{align*}
\pi \colon \Omega_{\mathcal{X}} \to \mathcal{X}.
\end{align*}

\label{lem:wtOmega}
For an object $\mathcal{E} \in \operatorname{Coh}(\Omega_{\mathcal{X}})$, we have the condition 
\begin{align*}
   \mathrm{wt}( \iota_{\overline{x}\ast}\nu_{\overline{x}}^{\mathrm{reg}\ast}(\mathcal{E})) \subset 
    \left[\frac{1}{2}c_1(T_{\Omega, \overline{x}}^{<0}), \frac{1}{2} c_1(T_{\Omega, \overline{x}}^{>0})  \right]
    +\frac{1}{2}c_1(\mathfrak{g}_{\overline{x}})+c_1(\nu^*\delta)
\end{align*}
if and only if 
\begin{align*}
   \mathrm{wt}( \iota_{x\ast}\overline{\nu}_x^{\mathrm{reg}\ast}(\mathcal{E}))
    \subset 
    \left[\frac{1}{2} c_1(T_{\mathcal{X}, x}^{<0}-T_{\mathcal{X}, x}^{>0}), 
    \frac{1}{2} c_1(T_{\mathcal{X}, x}^{>0}-T_{\mathcal{X}, x}^{<0})\right]
    +\frac{1}{2}c_1(\mathfrak{g}_x)+c_1(\nu^*\delta). 
\end{align*}

    We have the isomorphisms 
    \begin{align*}
\iota_{x\ast}\overline{\nu}_x^{\mathrm{reg}\ast}(\mathcal{E}) \cong 
\iota_{\overline{x}\ast}\eta_{\ast}\eta^{\ast}\nu_{\overline{x}}^{\mathrm{reg}\ast}(\mathcal{E}) 
\cong \iota_{\overline{x}\ast}\nu_{\overline{x}}^{\mathrm{reg}\ast}(\mathcal{E}) \otimes \bigwedge^{\bullet}W
    \end{align*}
    where $W=\mathfrak{g}_{x}/\mathfrak{g}_{\overline{x}}$. 
    From the distinguished triangle 
    \begin{align*}
        \pi^{\ast}\mathbb{L}_{\mathcal{X}} \to \mathbb{T}_{\Omega_{\mathcal{X}}} \to \pi^{\ast}
        \mathbb{T}_{\mathcal{X}}
    \end{align*}
    we have the short exact sequences of $\mathrm{Aut}(\overline{x})$-representations
    \begin{align*}
    0 \to W \to T_{\mathcal{X}, x}^{\vee} \to V \to 0, \ 
    0 \to V \to T_{\Omega, \overline{x}} \to V^{\vee} \to 0
    \end{align*}
    for some $\mathrm{Aut}(\overline{x})$-representation $V$. 

    Then we have the following identities
    \begin{align*}
        c_1\left(\frac{1}{2}T_{\Omega, \overline{x}}^{>0}+\frac{1}{2}\mathfrak{g}_{\overline{x}}+W^{>0}\right) &=c_1\left(
        \frac{1}{2}V^{>0}-\frac{1}{2}V^{<0}+\frac{1}{2}W^{>0}-\frac{1}{2}W^{<0}+\frac{1}{2}\mathfrak{g}_x\right) \\
        &=c_1\left(\frac{1}{2}(T_{\mathcal{X}, x}^{\vee})^{>0}-\frac{1}{2}(T_{\mathcal{X}, x}^{\vee})^{<0}+\frac{1}{2}\mathfrak{g}_x\right) \\
        &=c_1\left(-\frac{1}{2}T_{\mathcal{X}, x}^{<0}+\frac{1}{2}T_{\mathcal{X}, x}^{>0}+\frac{1}{2}\mathfrak{g}_x\right). 
    \end{align*}

    Similarly we have 
    \begin{align*}
        c_1\left(\frac{1}{2}T_{\Omega, \overline{x}}^{<0}+\frac{1}{2}\mathfrak{g}_{\overline{x}}+W^{<0}\right)
        =c_1\left(-\frac{1}{2}T_{\mathcal{X}, x}^{>0}+\frac{1}{2}T_{\mathcal{X}, x}^{<0}+\frac{1}{2}\mathfrak{g}_x\right).
    \end{align*}
    Therefore the lemma holds.

\begin{align*}
    0 \to W \to T_{\mathcal{X}, x}^{\vee} \to V \to 0, \ 
    0 \to V \to T_{\Omega, \overline{x}} \to V^{\vee} \to 0
    \end{align*}

\label{exam:O}
Let $0 \colon \mathcal{X} \to \Omega_{\mathcal{X}}$ be the zero section of the projection 
$\Omega_{\mathcal{X}}\to \mathcal{X}$. 
Then we have 
\begin{align*}
    0_{\ast}\mathcal{O}_{\mathcal{X}} \in \operatorname{L}(\Omega_{\mathcal{X}})_{-\frac{1}{2}}, \ 
   0_{\ast}\omega_{\mathcal{X}} \in \operatorname{L}(\Omega_{\mathcal{X}})_{\frac{1}{2}}.
\end{align*}
Indeed for a map $\nu \colon (B\mathbb{G}_m)_{k'} \to \Omega_{\mathcal{X}}$
with $x=\nu(0) \in 0(\mathcal{X})$, we have the Cartesian square 
\begin{align*}
    \xymatrix{
\mathfrak{g}_x^{\vee}[-1]/(\mathbb{G}_m)_{k'} \ar[r]^-{\overline{\nu}_x^{\mathrm{reg}}} \ar@{}[rd]|\square& \Omega_{\mathcal{X}} \\
T_{\mathcal{X}, x}^{\vee}[-1]/(\mathbb{G}_m)_{k'} \ar[r] \ar[u] & \mathcal{X} \ar[u]_-{0}.  
}
\end{align*}
It follows that $\iota_{x\ast}\overline{\nu}_x^{\mathrm{reg}\ast}0_{\ast}\mathcal{O}_{\mathcal{X}}=
\wedge^{\bullet}T_{\mathcal{X}, x}$, and the latter condition 
in Lemma~\ref{lem:wtOmega} is satisfied.

\label{lem:char2}
    An object $\mathcal{E} \in \operatorname{Coh}(\Omega_{\mathcal{X}})$ lies in 
    $\operatorname{L}(\Omega_{\mathcal{X}})_{\delta}$
    if and only if, for any $\nu \colon (B\mathbb{G}_m)_{k'} \to \Omega_{\mathcal{X}}$ such that 
    $\pi \circ \nu(0)=x \in X/G$, 
    we have
    \begin{align*}
        &\mathrm{wt}(\nu^{\ast}j^{\ast}j_{\ast}\mathcal{E})
        \subset \\
        &\left[ -\frac{1}{2}c_1((T_X|_{x} \oplus \Omega_X|_{x})^{>0}), 
        \frac{1}{2}c_1((T_X|_{x} \oplus \Omega_X|_{x})^{>0})
        \right]+\frac{1}{2}c_1(\mathfrak{g}_x)+c_1(\nu^*\delta).
    \end{align*}
    In particular, we have 
    \begin{enumerate}
\item for $\delta=\omega_{\mathcal{X}}^{1/2}$, the above condition is 
\begin{align*}
        \mathrm{wt}(\nu^{\ast}j^{\ast}j_{\ast}\mathcal{E})
        \subset \left[c_1 (\Omega_X|_{x}^{<0}), c_1(\Omega_X|_{x}^{>0}) \right]
        +c_1(\nu^{*}\mathfrak{g}). 
        \end{align*}
\item for $\delta=\omega_{\mathcal{X}}^{-1/2}$, the above condition is 
 \begin{align*}
        \mathrm{wt}(\nu^{\ast}j^{\ast}j_{\ast}\mathcal{E})
        \subset \left[c_1 (T_X|_{x}^{<0}), c_1(T_X|_{x}^{>0}) \right].
        \end{align*}    
        \end{enumerate}

The lemma immediately follows from Lemma~\ref{lem:emb}
by setting 
\begin{align*}\mathfrak{M}=\Omega_{\mathcal{X}},     \mathcal{Y}=\Omega_X/G, \ \mathcal{V}=(\Omega_X \times \mathfrak{g}^{\vee})/G, \ s=\mu. 
\end{align*}

By the Zariski descent of ind-coherent sheaves~\cite[Proposition~4.2.1]{MR3136100}, 
we have 
\begin{align*}
    \operatorname{IndCoh}(\mathfrak{M})=\lim_{\mathcal{U}\subset \mathfrak{M}}\operatorname{IndCoh}(\mathcal{U})
\end{align*}
where the limit is after quasi-compact open substacks $\mathcal{U}\subset \mathfrak{M}$ 
and pull-backs
\begin{align}\label{pull:j0}
j^{*}\colon 
    \operatorname{IndCoh}(\mathcal{U}_2) \to \operatorname{IndCoh}(\mathcal{U}_1)
\end{align}
for open immersions $j \colon \mathcal{U}_1 \hookrightarrow \mathcal{U}_2$.

\label{rmk:Ltilde}
We can also consider the limit 
\begin{align}\label{def:Ltilde}
\widetilde{\operatorname{L}}(\mathfrak{M})_{\delta}:=\lim_{\mathcal{U}\subset \mathfrak{M}}\operatorname{L}(\mathcal{U})_{\delta} 
\end{align}
where the limit is taken with respect to pull-backs (\ref{pback:L0}). 
We have $\operatorname{L}(\mathfrak{M})_{\delta}=\widetilde{\operatorname{L}}(\mathfrak{M})_{\delta}$ if $\mathfrak{M}$ is 
QCA, but this is not necessarily the case if $\mathfrak{M}$ is not QCA. 
The category (\ref{def:Ltilde}) will appear in Section~\ref{sec:hecke}.

We denote by 
\begin{align}\label{nilp:N}
    \mathcal{N}\subset \Omega_{\mathfrak{M}}[-1]
\end{align}
the closed substack consisting of nilpotent elements on fibers of (\ref{-1:shift}).

For an object $\mathcal{E} \in \operatorname{IndCoh}(\mathfrak{M})$, Arinkin-Gaitsgory~\cite{AG} 
associate the conical closed subset, called \textit{singular support}
\begin{align}\notag
    \mathrm{Supp}^{\mathrm{AG}}(\mathcal{E}) \subset \Omega_{\mathfrak{M}}[-1]. 
\end{align}

As in~\cite{AG}, we define the subcategory of nilpotent singular supports
\begin{align*}
    \operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M}) \subset \operatorname{IndCoh}(\mathfrak{M})
\end{align*}
to be consisting of objects whose singular supports are contained in $\mathcal{N}$.

\label{rmk:limit}
As we will discuss in Section~\ref{sec:Dmod}, 
the category $\operatorname{L}(\Omega_{\mathcal{X}})_{\frac{1}{2}}$ should be related to
the classical limit of the category of coherent D-modules 
$\text{D-mod}_{\mathrm{coh}}(\mathcal{X})$:
\begin{align*}
    \text{D-mod}_{\mathrm{coh}}(\mathcal{X}) \leadsto \operatorname{L}(\Omega_{\mathcal{X}})_{\frac{1}{2}}.
\end{align*}
For example, when $\mathcal{X}=BG$ for a reductive group $G$, the category $\operatorname{L}(\Omega_{\mathcal{X}})_{\frac{1}{2}}$ is equivalent to 
$\text{D-mod}_{\mathrm{coh}}(\mathcal{X})$, see Subsection~\ref{subsec:exam}. 
Similarly, as we discuss in Subsection~\ref{subsec:limsupp}, we expect $\operatorname{L}_{\mathcal{N}}(\Omega_{\mathcal{X}})_{\frac{1}{2}}$ to be related to the classical limit of the category of compact D-modules: 
\begin{align*}
    \text{D-mod}(\mathcal{X})^{\mathrm{cp}} \leadsto \operatorname{L}_{\mathcal{N}}(\Omega_{\mathcal{X}})_{\frac{1}{2}}.
\end{align*}

It is known that 
\begin{align}\label{cartan}
k[\mathfrak{h}[-2]]^W=k[y_2, y_4, \ldots, y_{2n}], \ \deg y_{2i}=2m_i, \ n=\dim \mathfrak{h}
\end{align}
for some $m_i\in \mathbb{Z}_{>0}$.

By~\cite[Theorem~3.3.1]{HalpK32}, 
there is a semiorthogonal decomposition 
\begin{align*}
    \operatorname{Coh}(\Omega_{\mathcal{X}})=\langle \ldots, \operatorname{Coh}(k[\epsilon])_{\lambda\text{-}\mathrm{wt}=-1}, \langle \mathcal{O}_{\Omega_{\mathcal{X}}} \rangle,  \operatorname{Coh}(k[\epsilon])_{\lambda\text{-}\mathrm{wt}=0}, \operatorname{Coh}(k[\epsilon])_{\lambda\text{-}\mathrm{wt}=1}, \ldots\rangle. 
\end{align*}

\label{rmk:D-mod3}
There is also a category of left D-modules, defined by 
\begin{align*}
    \text{D-mod}^l(\mathcal{X}):=\operatorname{QCoh}(\mathcal{X}_{\mathrm{dR}}). 
\end{align*}
There is a canonical equivalence, see~\cite{MR3701353}:
\begin{align}\label{equiv:rl}
    \Upsilon \colon \text{D-mod}^l(\mathcal{X}) \stackrel{\sim}{\to} 
    \text{D-mod}(\mathcal{X}), \ \mathcal{E} \mapsto \mathcal{E}\otimes \omega_{\mathcal{X}_{\mathrm{dR}}}. 
\end{align}

By~\cite[Theorem~1.1]{McNe}, the above recollement diagram restricts to the 
recollement diagram
\begin{align}\label{dia:recoll3}
\xymatrix{\text{D-mod}_{\mathrm{coh}}(B\mathbb{G}_m) \ar[r]^-{i_{*}} & \text{D-mod}_{\mathrm{coh}}(\mathcal{X}) \ar[r]^-{j^*} \ar@/^18pt/[l]_-{i^!} \ar@/_18pt/[l]_-{i^*}& 
\text{D-mod}_{\mathrm{coh}}(\mathrm{pt}). \ar@/^18pt/[l]_-{j_*} \ar@/_18pt/[l]_-{j_!}
}
\end{align}

One can check that 
\begin{align*}
