\end{align*}

\label{lem:ssupport}
For an object $\mathcal{E}\in \operatorname{IndCoh}(\Omega_{\mathcal{X}})$, we have 
\begin{align*}
    \mathrm{Supp}^L(\mathcal{E}) \subset \mathrm{Nilp}(\mathfrak{g})/G
\end{align*}
if and only if $\mathcal{E}\in \operatorname{IndCoh}_{\mathcal{N}}(\Omega_{\mathcal{X}})$. 
Here $\mathrm{Nilp}(\mathfrak{g})\subset \mathfrak{g}$ is the nilpotent cone.

The monoidal action (\ref{maction:lim}) is given by     
\begin{align*}
    f^{\Omega!}(A)\otimes^{\Omega !} B &= \Delta^{\Omega !}(f^{\Omega!}(A) \boxtimes B) \\
    &=\Delta^{\Omega!}(f\times \operatorname{id})^{\Omega !}(A\boxtimes B) \\
    &=g^{\Omega!}(A\boxtimes B)
\end{align*}
where $g=(f, \operatorname{id}) \colon \mathcal{X}\to BG\times \mathcal{X}$. 
It is then given by $\beta_* \alpha^!$ for the diagram 
\begin{align}\label{dia:mon1}
    \xymatrix{
    \Omega_{\mathcal{X}} \ar[d] & \mathcal{Y}
    \ar[l]_-{\beta} \ar[r]^-{\alpha} \ar[d] \ar@{}[rd]|\square& \Omega_{BG}\times \Omega_{\mathcal{X}} \ar[d] \\
    \mathcal{X} \ar@{=}[r] & \mathcal{X} \ar[r]^-{g} & BG \times \mathcal{X}.  
    }
\end{align}
Here, the right square is Cartesian. 

Note that we have 
\begin{align*}
    \Omega_{BG} \simeq \mathfrak{g}^{\vee}[-1]/G \simeq 0/G \times_{\mathfrak{g}^{\vee}/G}0/G
\end{align*}
where $0\in \mathfrak{g}^{\vee}$ is the origin. We also have equivalences
\begin{align*}
    \mathcal{Y} &\simeq  \Omega_{\mathcal{X}}\times_{BG}\Omega_{BG} \\
    &\simeq \Omega_{\mathcal{X}}\times_{BG}(0/G \times_{\mathfrak{g}^{\vee}/G}0/G) \\
    &\simeq \Omega_{\mathcal{X}}\times_{\mathfrak{g}^{\vee}/G}\times 0/G \\
    &\simeq \Omega_{\mathcal{X}}\times_{\Omega_{X/G}}(\Omega_{X/G}\times_{\mathfrak{g}^{\vee}/G}0/G)\\
    &\simeq \Omega_{\mathcal{X}}\times_{\Omega_{X/G}}\times \Omega_{\mathcal{X}}.
\end{align*}

Under the above equivalences, the monoidal action $g^{\Omega!}=\beta_{*}\alpha^!$
in the diagram (\ref{dia:mon1}) is identified with the monoidal action 
induced by the diagram 
\begin{align}\label{dia:mon2}
    \xymatrix{
    \Omega_{\mathcal{X}} \ar[d] & \Omega_{\mathcal{X}}\times_{\Omega_X/G} \Omega_{\mathcal{X}}
    \ar[l] \ar[r] \ar[d] &  \Omega_{\mathcal{X}} \ar[d] \\
    BG & \ar[l] 0/G\times_{\mathfrak{g}^{\vee}/G}0/G \ar[r] & BG.  
    }
\end{align}
Here the horizontal arrows are projections onto the corresponding 
factors. The monoidal action of $\operatorname{IndCoh}(\Omega_{BG})$ induced by 
the diagram (\ref{dia:mon2}) is used to characterize Arinkin-Gaitsgory singular 
supports in~\cite[Section~9.2]{AG}. The lemma now follows 
from~\cite[Lemma~9.2.6]{AG}.

\label{cor:nilp}
The subcategories 
\begin{align*}
