\end{enumerate}

\label{lem:funct2}
Consider the derived Cartesian square of smooth stacks 
\begin{align*}
    \xymatrix{
\mathcal{X}_4 \ar[r]^-{f_4} \ar[d]_-{f_3} \ar@{}[rd]|\square& \mathcal{X}_1 \ar[d]^-{f_1} \\
\mathcal{X}_3 \ar[r]^-{f_2} & \mathcal{X}_2.     
    }
\end{align*}
Suppose that $f_1, f_3$ are schematic.
Then we have 
\begin{align*}
   f_2^{\Omega!} \circ f_{1\ast}^{\Omega} \cong f_{3\ast}^{\Omega} \circ f_4^{\Omega!}
   \colon \operatorname{IndCoh}(\Omega_{\mathcal{X}_1}) \to \operatorname{IndCoh}(\Omega_{\mathcal{X}_3}).
\end{align*}

\label{lem:funct3}
(i) For a morphism $f\colon \mathcal{X} \to \mathcal{Y}$ of smooth stacks, we have 
\begin{align*}
    f^{\Omega!}(-)\otimes^{\Omega!}f^{\Omega!}(-)\cong f^{\Omega!}(-\otimes^{\Omega!}-)
    \end{align*}
    as functors
    \begin{align*} 
    \operatorname{IndCoh}(\Omega_{\mathcal{Y}})\otimes \operatorname{IndCoh}(\Omega_{\mathcal{Y}}) \to \operatorname{IndCoh}(\Omega_{\mathcal{X}}).
    \end{align*}

(ii) For a schematic morphism $f\colon \mathcal{X} \to \mathcal{Y}$ of smooth stacks, we have 
\begin{align*}
    f^{\Omega}_{*}(-)\otimes^{\Omega!}(-)\cong f^{\Omega}_{*}(-\otimes^{\Omega!}f^{\Omega!}(-))\end{align*}
    as functors \begin{align*} 
    \operatorname{IndCoh}(\Omega_{\mathcal{Y}})\otimes \operatorname{IndCoh}(\Omega_{\mathcal{X}}) \to \operatorname{IndCoh}(\Omega_{\mathcal{X}}).
\end{align*}

Let $\nu$ be a map 
\begin{align*}
\nu \colon (B\mathbb{G}_m)_{k'} \to f^{\ast}\Omega_{\mathcal{Y}}, \ 0\mapsto z.

\label{lem:pull}
For $\mathcal{E} \in \operatorname{Coh}(\Omega_{\mathcal{Y}})$, we have 
\begin{align*}
    \mathrm{wt}(\iota_{y\ast}\overline{\nu}_y^{\mathrm{reg}\ast}(\mathcal{E})) \subset 
     \left[\frac{1}{2}c_1(T_{\mathcal{Y}, y}^{<0}-T_{\mathcal{Y}, y}^{>0}),  \frac{1}{2}c_1(T_{\mathcal{Y}, y}^{>0}-T_{\mathcal{Y}, y}^{<0})  \right]+\frac{1}{2}c_1(\mathfrak{g}_y)+c_1(\nu^*\delta)
\end{align*}
if and only if 
\begin{align*}
    \mathrm{wt}(\iota_{x\ast}\overline{\nu}_x^{\mathrm{reg}\ast}\beta_{\ast}\alpha^{!}(\mathcal{E})) \subset 
     \left[\frac{1}{2}c_1(T_{\mathcal{X}, x}^{<0}-T_{\mathcal{X}, x}^{>0}),  \frac{1}{2}c_1(T_{\mathcal{X}, x}^{>0}-T_{\mathcal{X}, x}^{<0})  \right]+\frac{1}{2}c_1(\mathfrak{g}_x)+c_1(\nu^*\delta')
\end{align*}
where $\delta'=f^{\ast}\delta \otimes \omega_{f}^{1/2}$.

By the distinguished triangle 
\begin{align*}
    \mathbb{T}_f \to \mathbb{T}_{\mathcal{X}} \to f^{\ast}\mathbb{T}_{\mathcal{Y}}
\end{align*}
and using that $f$ is smooth, there are exact sequences
of $\mathrm{Aut}(x)$-representations
\begin{align}\notag
    &0 \to A \to \mathfrak{g}_x \to B \to 0, \ 
    0 \to B \to \mathfrak{g}_y \to W \to 0, \\
    \label{exact:AB}&0 \to W \to N \to V \to 0, \ 0 \to V \to 
    T_{\mathcal{X}, x} \to T_{\mathcal{Y}, y} \to 0
\end{align}
where $A=\mathcal{H}^{-1}(\mathbb{T}_f|_{x})$
and $N=\mathcal{H}^0(\mathbb{T}_f|_{x})$
and $\mathcal{H}^i(\mathbb{T}_f|_{x})=0$ for $i\neq -1, 0$. 

On the other hand, the map $f^*\Omega_{\mathcal{Y}}\hookrightarrow \Omega_{\mathcal{X}}$ on fibers 
at $x\in \mathcal{X}(k')$ is given by 
$\mu_y^{-1}(0)\to \mu_x^{-1}(0)$, induced by the commutative 
diagram 
\begin{align*}
    \xymatrix{
T_{\mathcal{Y}, y}^{\vee} \ar[r]^-{\mu_y} \ar[d] & \mathfrak{g}_y^{\vee} \ar[d] \\
T_{\mathcal{X}, x}^{\vee} \ar[r]^-{\mu_x}  & \mathfrak{g}_x^{\vee}.  
    }
\end{align*}
Together with the last exact sequence of (\ref{exact:AB}), 
we have the commutative diagram 
\begin{align*}
    \xymatrix{
\Omega_{\mathcal{X}} \ar@{}[rd]|\square& f^{\ast}\Omega_{\mathcal{Y}} \ar@<0.3ex>@{_{(}->}[l]_-{\beta}
 \ar[r]^-{\alpha} & \Omega_{\mathcal{Y}} \\
 \mathfrak{g}_x^{\vee}[-1]/(\mathbb{G}_m)_{k'} \ar[rd]_-{\iota_x} \ar[u]^-{\overline{\nu}_x^{\mathrm{reg}}} & 
 (\mathfrak{g}_y \oplus V)^{\vee}[-1]/(\mathbb{G}_m)_{k'} \ar[r]^-{\eta_2} \ar[l]_-{\eta_1}  \ar[u]^-{\overline{\nu}_z^{\mathrm{reg}}}\ar[d]_-{\iota_{z}}& \mathfrak{g}_y^{\vee}[-1]/(\mathbb{G}_m)_{k'} 
 \ar[ld]^-{\iota_y} \ar[u]_-{\overline{\nu}_y^{\mathrm{reg}}} \\
 &(B\mathbb{G}_m)_{k'}.  &
    }
\end{align*}
In the above, the top left square is Cartesian, $\overline{\nu}_z^{\mathrm{reg}}$ is defined by the 
above commutative diagram, 
and $\eta_2$ is the projection. 

Let $\nu_x$ be the composition 
$(B\mathbb{G}_m)_{k'} \stackrel{\nu_{\overline{x}}}{\to} \Omega_{\mathcal{X}} \to \mathcal{X}$.
For $\mathcal{E} \in \operatorname{Coh}(\Omega_{\mathcal{Y}})$, we have 
the isomorphisms 
\begin{align*}    \iota_{x\ast}\overline{\nu}_x^{\mathrm{reg}\ast}\beta_{\ast}\alpha^{!}\mathcal{E} &\cong \iota_{x\ast}\eta_{1\ast}\overline{\nu}_z^{\mathrm{reg}\ast}\alpha^{!}\mathcal{E} \\
&\cong \iota_{z\ast}\overline{\nu}_z^{\mathrm{reg}\ast}\alpha^{!}\mathcal{E} \\
& \cong \iota_{z\ast}\eta_2^{\ast}\overline{\nu}_y^{\mathrm{reg}\ast}\mathcal{E}\otimes \nu_x^*(\omega_f[\dim f]) \\
&\cong \iota_{y\ast}\eta_{2\ast}\eta_2^{\ast}\overline{\nu}_y^{\mathrm{reg}\ast}\mathcal{E}\otimes \nu_x^*(\omega_f[\dim f]) \\
&\cong \iota_{y\ast}\overline{\nu}_y^{\mathrm{reg}\ast}\mathcal{E}\otimes \nu_x^*(\omega_f[\dim f])\otimes 
\wedge^{\bullet}V. 
\end{align*}
  It follows that 
the weights
$\mathrm{wt}(\iota_{y\ast}\overline{\nu}_y^{\mathrm{reg}\ast}(\mathcal{E}))$ lie in $[a, b]$ if and only if 
\begin{align*}
    \mathrm{wt}(\iota_{x\ast}\overline{\nu}_x^{\mathrm{reg}\ast}(\mathcal{E}))
    \subset [a+c_1(V^{<0}), b+c_1(V^{>0})]+c_1(\omega_f|_{x}). 
\end{align*}
We have the following equality in $K((B\mathbb{G}_m)_{k'})$
\begin{align*}
    &\frac{1}{2}T_{\mathcal{Y}, y}^{>0}-\frac{1}{2}T_{\mathcal{Y}, y}^{<0}
    +\frac{1}{2}\mathfrak{g}_y+V^{>0}+\omega_f|_{x}  \\
    &=\frac{1}{2}(T_{\mathcal{X}, x}-V)^{>0}-\frac{1}{2}(T_{\mathcal{X}, x}-V)^{<0}+\frac{1}{2}(\mathfrak{g}_x+W-A)+V^{>0} +\omega_f|_{x} \\
    &=\frac{1}{2}T_{\mathcal{X}, x}^{>0}-\frac{1}{2}T_{\mathcal{X}, x}^{<0}
    +\frac{1}{2}\mathfrak{g}_x+\frac{1}{2}(N-A)+\omega_f|_{x}. 
\end{align*}

Similarly, we have 
\begin{align*}
\frac{1}{2}T_{\mathcal{Y}, y}^{<0}-\frac{1}{2}T_{\mathcal{Y}, y}^{>0}
    +\frac{1}{2}\mathfrak{g}_y+V^{<0} 
    =\frac{1}{2}T_{\mathcal{X}, x}^{<0}-\frac{1}{2}T_{\mathcal{X}, x}^{>0}
    +\frac{1}{2}\mathfrak{g}_x+\frac{1}{2}(N-A)+\omega_f|_{x}. 
    \end{align*}
    Note that $\det (N-A)=\omega_{f}^{-1}|_{x}$. 
    Therefore the lemma holds.

\label{prop:pback}
For a smooth morphism $f \colon \mathcal{X} \to \mathcal{Y}$, the 
functor (\ref{pback!})
restricts to a functor
\begin{align}\label{funct:pback}f^{\Omega!} \colon 
    \operatorname{L}(\Omega_{\mathcal{Y}})_{\delta\otimes \omega_{\mathcal{Y}}^{1/2}} \to \operatorname{L}(\Omega_{\mathcal{X}})_{f^{\ast}\delta \otimes \omega_{\mathcal{X}}^{1/2}}  
\end{align}

\label{lem:pull2}
Suppose that $f$ is a closed immersion. 
For $\mathcal{E} \in \operatorname{Coh}(\Omega_{\mathcal{X}})$, we have 
\begin{align*}
   \mathrm{wt}( \iota_{x\ast}\overline{\nu}_x^{\mathrm{reg}\ast}(\mathcal{E})) \subset 
    & \left[\frac{1}{2}c_1(T_{\mathcal{X}, x}^{<0}-T_{\mathcal{X}, x}^{>0}),  \frac{1}{2}c_1(T_{\mathcal{X}, x}^{>0}-T_{\mathcal{X}, x}^{<0})  \right]+\frac{1}{2}c_1(\mathfrak{g}_x)+c_1(\nu^*f^*\delta)
\end{align*}
if and only if 
\begin{align*}
   \mathrm{wt}( \iota_{y\ast}\overline{\nu}_y^{\mathrm{reg}\ast}\alpha_{\ast}\beta^{\ast}(\mathcal{E})) \subset 
    & \left[\frac{1}{2}c_1(T_{\mathcal{Y}, y}^{<0}-T_{\mathcal{Y}, y}^{>0}),  \frac{1}{2}c_1(T_{\mathcal{Y}, y}^{>0}-T_{\mathcal{Y}, y}^{<0})  \right] +\frac{1}{2}c_1(\mathfrak{g}_x)+c_1(\nu^*\delta')
\end{align*}
where $\delta'=\delta \otimes \omega_{f}^{-1/2}$.

\label{thm:proj}
Let $f \colon \mathcal{X} \to \mathcal{Y}$ be a projective morphism of smooth QCA stacks. 
Then the functor (\ref{ppush}) 
restricts to the functor 
    \begin{align}\label{funct:Lpush}
        f^{\Omega}_{*} \colon 
    \operatorname{L}(\Omega_{\mathcal{X}})_{f^{\ast}\delta\otimes \omega_{\mathcal{X}}^{1/2}} \to \operatorname{L}(\Omega_{\mathcal{Y}})_{\delta \otimes \omega_{\mathcal{Y}}^{1/2}}. 
    \end{align}

    For $\mathcal{E} \in \operatorname{L}(\Omega_{\mathcal{X}})_{f^{\ast}\delta \otimes \omega_{\mathcal{X}}^{1/2}}$, 
    we need to show that $f^{\Omega}_{\ast}\mathcal{E} \in \operatorname{Coh}(\Omega_{\mathcal{Y}})$ 
    satisfies the condition in Lemma~\ref{lem:wtOmega}.
    Let $\nu \colon (B\mathbb{G}_m)_{k'} \to \Omega_{\mathcal{Y}}$ be a map 
    with composition
    \begin{align*}
      \nu_y \colon (B\mathbb{G}_m)_{k'} \to \Omega_{\mathcal{Y}} \stackrel{\pi_{\mathcal{Y}}}{\to} \mathcal{Y}, \ 
      0 \mapsto y. 
    \end{align*}
    We may assume that the induced cocharacter $(\mathbb{G}_m)_{k'} \to \mathrm{Aut}(y)$ is injective. As in Remark~\ref{rmk:k'}, we may assume that $k'$ is 
    algebraically closed. Then by replacing $\mathcal{Y}$ with $\mathcal{Y}_{k'}$, we may further assume that $k'=k$. 

    Then by~\cite[Theorem~1.1]{AHRLuna}, there is an affine $k$-scheme $Y=\operatorname{Spec} A$ with 
    $(\mathbb{G}_m)$-action, 
    a $\mathbb{G}_m$-fixed point $0 \in Y$ and a smooth morphism 
    $g \colon Y/\mathbb{G}_m \to \mathcal{Y}$ such that $g|_{0/\mathbb{G}_m}=\nu_y$. 
We have the induced functor 
\begin{align*}
    g^{\Omega!} \colon \operatorname{Coh}(\mathcal{Y}) \to \operatorname{Coh}(Y/\mathbb{G}_m). 
\end{align*}
    By Lemma~\ref{lem:pull}, we have 
    $f^{\Omega}_{\ast}(\mathcal{E}) \in \operatorname{L}(\Omega_{\mathcal{Y}})_{\delta \otimes \omega_{\mathcal{Y}}^{1/2}}$ if 
    and only if 
    \begin{align}\label{gf1}
    g^{\Omega!}f^{\Omega}_{\ast}(\mathcal{E})
    \in \operatorname{L}(Y/\mathbb{G}_m)_{g^{\ast}\delta \otimes g^{\ast}\omega_{\mathcal{Y}}^{1/2} \otimes \omega_g^{1/2}}
    = \operatorname{L}(Y/\mathbb{G}_m)_{g^*\delta\otimes\omega_{Y/\mathbb{G}_m}^{1/2}}
    \end{align}
    for any map $\nu$ as above. We have the Cartesian square 
    \begin{align*}
        \xymatrix{
X/\mathbb{G}_m \ar[r]^-{g'} \ar[d]_-{f'} \ar@{}[rd]|\square& \mathcal{X} \ar[d]^-{f} \\
Y/\mathbb{G}_m \ar[r]^-{g} & \mathcal{Y}        
        }
    \end{align*}
    where $X=\mathcal{X}\times_{\mathcal{Y}}Y$. Since $f$ is projective, 
    we have that $X$ is a smooth $k$-scheme which is projective over $Y$. 
    By Lemma~\ref{lem:funct2}, we have the isomorphism
    \begin{align}\label{gf2}
       g^{\Omega!}f^{\Omega}_{\ast}(\mathcal{E})
       \cong (f')^{\Omega}_{\ast} (g')^{\Omega!}(\mathcal{E}). 
    \end{align}
    By Proposition~\ref{prop:pback}, we have 
    \begin{align}\label{gf3}
        (g')^{\Omega!}(\mathcal{E}) \in \operatorname{L}(\Omega_{X/\mathbb{G}_m})_{g^{'\ast}\omega_{\mathcal{X}}^{1/2}\otimes g^{'\ast}f^*\delta\otimes\omega_{g'}^{1/2}}=\operatorname{L}(\Omega_{X/\mathbb{G}_m})_{f^{'\ast}g^*\delta\otimes\omega_{X/\mathbb{G}_m}^{1/2}}.
    \end{align}
By (\ref{gf2}) and (\ref{gf3}), it is enough to show that 
the object (\ref{gf3}) applied to $(f')^{\Omega}_{*}$ satisfies (\ref{gf1}). 
    Therefore, we can replace 
$(\mathcal{X}, \mathcal{Y})$ with $(X/\mathbb{G}_m, Y/\mathbb{G}_m)$. 

By~\cite[Theorem~5.2.1]{Brion0}, there 
is an $f'$-ample $\mathbb{G}_m$-linearized 
line bundle on $X$. By shrinking $Y$ if necessary, 
we obtain the commutative diagram 
\begin{align*}
\xymatrix{
X/\mathbb{G}_m \ar@<-0.3ex>@{^{(}->}[r]^-{i} \ar[d]_-{f'}& \mathbb{P}_Y^n /\mathbb{G}_m\ar[ld]^-{f''} 
\\
Y/\mathbb{G}_m &
}
\end{align*}
where $i$ is a closed immersion, 
$\mathbb{P}_Y^n=\mathbb{P}^n \times Y$,
and $\mathbb{G}_m$ acts on $\mathbb{P}^n$ linearly. 
By Lemma~\ref{lem:funct}, 
we have $(f'')^{\Omega}_{\ast}i^{\Omega}_{\ast}=(f')^{\Omega}_{\ast}$. 
Also by Proposition~\ref{prop:push} and (\ref{gf3}), we have 
\begin{align*}
    i^{\Omega}_{\ast}(g')^{\Omega!}(\mathcal{E}) \in     \operatorname{L}(\Omega_{\mathbb{P}_Y^n/\mathbb{G}_m})_{ f^{''\ast}g^*\delta \otimes \omega_{\mathbb{P}_Y^n/\mathbb{G}_m}^{1/2}}. 
\end{align*}
Therefore we can replace $(X, f')$ with $(\mathbb{P}_Y^n, f'')$, and it is enough 
to prove the proposition for the object 
$\mathcal{E}'=i^{\Omega}_{\ast}(g')^{\Omega!}(\mathcal{E})$
with respect to $f''$. 

We have the following commutative diagram 
\begin{align*}
    \xymatrix{
\Omega_{\mathbb{P}_Y^n/\mathbb{G}_m} \ar@<-0.3ex>@{^{(}->}[d]_-{j_1}\ar@{}[rd]|\square
& \ar@<0.3ex>@{_{(}->}[l]_-{\beta_1}
f^{''\ast}\Omega_{Y/\mathbb{G}_m} \ar[r]^-{\alpha_1} \ar@<-0.3ex>@{^{(}->}[d]_-{j_2}\ar@{}[rd]|\square
&
\Omega_{Y/\mathbb{G}_m} \ar@<-0.3ex>@{^{(}->}[d]_-{j_3} \\
\Omega_{\mathbb{P}_Y^n}/\mathbb{G}_m &(\mathbb{P}^n \times \Omega_Y)/\mathbb{G}_m \ar[r]^-{\alpha_2} \ar@<0.3ex>@{_{(}->}[l]_-{\beta_2} & \Omega_Y/\mathbb{G}_m  
    }
\end{align*}
where the vertical arrows are closed immersions, 
each square is Cartesian, $\beta_2$ is the product with the zero section 
$\mathbb{P}^n \hookrightarrow \Omega_{\mathbb{P}^n}$ and $\alpha_2$ is the projection. 
By the base change, we have 
\begin{align*}
    j_{3\ast}\alpha_{1\ast}\beta_1^{\ast}\mathcal{E}'
    \cong \alpha_{2\ast}j_{2\ast}\beta_1^{\ast}\mathcal{E}' 
    \cong \alpha_{2\ast}\beta_2^{\ast}j_{1\ast}\mathcal{E}'. 
\end{align*}
By Lemma~\ref{lem:char2}, we need to show 
the following: for any $\mathbb{G}_m$-fixed
point $\overline{q} \in \Omega_{Y}$ with $\pi_{Y}(\overline{q})=q$, 
where $\pi_Y \colon \Omega_Y \to Y$ is the projection, 
we have 
\begin{align}\label{wtcond:m}    \mathrm{wt}((\alpha_{2\ast}\beta_2^{\ast}j_{1\ast}\mathcal{E}')|_{\overline{q}}) \subset [m_1, m_2]+c_1((g^*\delta)|_{q}) 
\end{align}
where $m_i$ are given by 
\begin{align}\label{def:m}
m_1=c_1 (\Omega_Y|_{q}^{<0}), \ m_2=c_1 (\Omega_Y|_{q}^{>0}). 
\end{align}

Note that 
\begin{align*}    (\alpha_{2\ast}\beta_2^{\ast}j_{1\ast}\mathcal{E}')|_{\overline{q}}\cong     \Gamma(\mathbb{P}^n, (\beta_2^{\ast}j_{1\ast}\mathcal{E}')|_{\mathbb{P}^n\times \overline{q}}).
\end{align*}
By Lemma~\ref{lem:char2}, the object 
$\beta_2^{\ast}j_{1\ast}\mathcal{E}'$ satisfies 
the following: 
for any $\mathbb{G}_m$-fixed point 
$(p, \overline{q}) \in \mathbb{P}^n \times \Omega_Y$
with $\pi_{\mathcal{Y}}(\overline{q})=q$, 
we have 
\begin{align}\label{wtcond:m2}
    \mathrm{wt}((\beta_2^{\ast}j_{1\ast}\mathcal{E})|_{(p, \overline{q})}) \subset 
     \left[c_1(\Omega_{\mathbb{P}^n}|_{p}^{<0}), c_1(\Omega_{\mathbb{P}^n}|_{p}^{>0}) \right]
     +[m_1, m_2]
     +c_1((g^*\delta)|_{q})
\end{align}
where $m_i$ are given by (\ref{def:m}).
Then the condition (\ref{wtcond:m}) follows from (\ref{wtcond:m2}) and Lemma~\ref{lem:wtbound} below.

\label{lem:wtbound}
Let $\mathbb{G}_m$ act on $\mathbb{P}^n$ linearly. 
For $\mathcal{E} \in \operatorname{Coh}(\mathbb{P}^n/\mathbb{G}_m)$, 
suppose that for any $\mathbb{G}_m$-fixed point 
$p \in \mathbb{P}^n$ we have 
\begin{align*}
    \mathrm{wt}(\mathcal{E}|_{p}) \subset \left[c_1 (\Omega_{\mathbb{P}^n}|_{p}^{<0}), 
    c_1 (\Omega_{\mathbb{P}^n}|_{p}^{>0})
    \right]+[m_1, m_2]
\end{align*}
for $m_1 \leqslant m_2$. 
Then we have 
\begin{align*}
    \mathrm{wt}(\Gamma(\mathbb{P}^n, \mathcal{E}))
    \subset [m_1, m_2]. 
\end{align*}

    Let $f \colon \mathbb{P}^n/\mathbb{G}_m \to B\mathbb{G}_m$. We take $k>m_2$. 
    Then by Lemma~\ref{lem:Pn}, we have
\begin{align*}
    \operatorname{Hom}(f^{\ast}\mathcal{O}_{B\mathbb{G}_m}(k), 
    \mathcal{E}) =\operatorname{Hom}(\mathcal{O}_{B\mathbb{G}_m}(k), f_{\ast}\mathcal{E})=0. 
\end{align*}
    Therefore we have 
    \begin{align}\label{f*E}
        f_{\ast}\mathcal{E} \in \operatorname{Coh}(B\mathbb{G}_m)_{\leqslant m_2}. 
    \end{align}

    We also have the condition 
  \begin{align*}
    \mathrm{wt}(\mathcal{E}^{\vee} \otimes \omega_{\mathbb{P}^N}|_{p}) \subset \left[c_1 (\Omega_{\mathbb{P}^n}|_{p}^{<0}), 
    c_1 (\Omega_{\mathbb{P}^n}|_{p}^{>0})
    \right]+[-m_2, -m_1].
\end{align*}  
By applying (\ref{f*E}) for $\mathcal{E}^{\vee}\otimes \omega_{\mathbb{P}^n}[n]$, we
have that 
\begin{align*}
    f_{\ast}(\mathcal{E}^{\vee}\otimes \omega_{\mathbb{P}^n}[n])
    \cong f_{\ast}(\mathcal{E})^{\vee} \in 
    \operatorname{Coh}(B\mathbb{G}_m)_{\leqslant -m_1}
\end{align*}
where the first isomorphism is Serre duality. 
Therefore we have 
\begin{align*}
    f_{\ast}\mathcal{E} \in \operatorname{Coh}(B\mathbb{G}_m)_{\geqslant m_1}
\end{align*}
and the lemma holds.

\label{cor:adjoint}
Suppose that $f \colon \mathcal{X} \to \mathcal{Y}$ is a
smooth projective morphism of smooth QCA stacks. We have 
the adjoint pair of functors 
\begin{align*}
    &f^{\Omega!} \colon \operatorname{L}(\Omega_{\mathcal{Y}})_{\delta\otimes \omega_{\mathcal{Y}}^{1/2}} \to \operatorname{L}(\Omega_{\mathcal{X}})_{f^{\ast}\delta \otimes \omega_{\mathcal{X}}^{1/2}}, \\
    &f^{\Omega}_{*} \colon \operatorname{L}(\Omega_{\mathcal{X}})_{f^{\ast}\delta\otimes \omega_{\mathcal{X}}^{1/2}} \to \operatorname{L}(\Omega_{\mathcal{Y}})_{\delta \otimes \omega_{\mathcal{Y}}^{1/2}}
\end{align*}
where $f^{\Omega!}$ is the right adjoint functor of 
$f^{\Omega}_{*}$.

\emph{(\cite[Proposition~2.4]{T2})}\label{prop:singss}

(i) Assume that $\alpha$ is quasi-smooth and $\beta$ is proper. 
Then for $\mathcal{E} \in \operatorname{Coh}(\Omega_{\mathcal{Y}})$ we have 
\begin{align*}
    \mathrm{Supp}^{\mathrm{AG}}(\beta_{*}\alpha^! \mathcal{E}) \subset vu^{-1}(\mathrm{Supp}^{\mathrm{AG}}(\mathcal{E}))
    \subset \Omega_{\Omega_{\mathcal{X}}}[-1].
\end{align*}

(ii) Assume that $\beta$ is quasi-smooth and $\alpha$ is proper. 
Then for $\mathcal{E} \in \operatorname{Coh}(\Omega_{\mathcal{X}})$ we have 
\begin{align*}
    \mathrm{Supp}^{\mathrm{AG}}(\alpha_{*}\beta^* \mathcal{E}) \subset uv^{-1}(\mathrm{Supp}^{\mathrm{AG}}(\mathcal{E}))
    \subset \Omega_{\Omega_{\mathcal{Y}}}[-1].
\end{align*}

\label{fib:F}
The classical truncation $F_z$ of the fiber of the projection (\ref{def:-2}) at $z$ is given by the kernel 
of a map $\mathfrak{g}_{x} \to T_{\mathcal{Y}, y}^{\vee}$.

Let $\pi \colon f^* \Omega_{\mathcal{Y}} \to \mathcal{X}$ be the projection. 
Let $\gamma \colon f^* \mathbb{L}_{\mathcal{Y}} \to \mathbb{L}_{\mathcal{X}}$ be induced by $f$. 
We have the following commutative diagram 
\begin{align*}
    \xymatrix{
\pi^* \mathbb{L}_{\mathcal{X}} \oplus \pi^{*}f^* \mathbb{L}_{\mathcal{Y}} \ar[r] \ar[d]_-{\operatorname{id}+\pi^* \gamma} & 
(\alpha, \beta)^* \mathbb{L}_{\Omega_{\mathcal{X}}\times \Omega_{\mathcal{Y}}} \ar[r] \ar[d] & \pi^* \mathbb{T}_{\mathcal{X}}\oplus \pi^* f^* \mathbb{T}_{\mathcal{Y}} \ar[d]^-{\operatorname{id}+\pi^* \gamma^{\vee}} \\
\pi^* \mathbb{L}_{\mathcal{X}} \ar[r] & \mathbb{L}_{f^{*}\Omega_{\mathcal{Y}}} \ar[r] & \pi^* f^* \mathbb{T}_{\mathcal{Y}}.
    }
\end{align*}
    Here each horizontal sequence is a distinguished triangle. Considering the cones of vertical maps, we obtain 
    the distinguished triangle 
    \begin{align*}
        \pi^* f^* \mathbb{L}_{\mathcal{Y}} \to \mathbb{L}_{(\alpha, \beta)}[-1] \to \pi^* \mathbb{T}_{\mathcal{X}}. 
    \end{align*}
    Therefore we obtain the exact sequence 
    \begin{align*}
        0\to \mathcal{H}^{-2}(\mathbb{L}_{(\alpha, \beta)}|_{z}) \to \mathfrak{g}_x \to T_{\mathcal{Y}, y}^{\vee}
    \end{align*}
    which proves the lemma.

\label{def:nileff}
We say that a morphism $f\colon \mathcal{X} \to \mathcal{Y}$ of stacks is \textit{nil-effective} if 
for any $x\in \mathcal{X}(k')$ with $y=f(x)\in \mathcal{Y}(k')$, the induced morphism 
$\phi \colon \mathfrak{g}_x \to \mathfrak{g}_y$ satisfies 
\begin{align*}
    \mathrm{Nilp}(\mathfrak{g}_x)=\phi^{-1}(\mathrm{Nilp}(\mathfrak{g}_y)).
\end{align*}

\label{lem:nilpotent}
(i) In Proposition~\ref{prop:singss} (i), assume in addition that $f$ (hence $\alpha$) is nil-effective. 
Then we have 
\begin{align*}
    vu^{-1}(\mathcal{N}_{\mathcal{Y}}) \subset \mathcal{N}_{\mathcal{X}} \subset \Omega_{\Omega_{\mathcal{X}}}[-1].
\end{align*}
  (ii) In Proposition~\ref{prop:singss} (ii), we have 
\begin{align*}
    uv^{-1}(\mathcal{N}_{\mathcal{X}}) \subset \mathcal{N}_{\mathcal{Y}} \subset \Omega_{\Omega_{\mathcal{X}}}[-1].
\end{align*}

For $z\in f^*\Omega_{\mathcal{Y}}(k')$, let $F_z$ be as in Lemma~\ref{fib:F}. 
    The map 
    \begin{align*}
        F_z \stackrel{v|_{F_z}}{\to} \mathfrak{g}_{\overline{x}} \subset \mathfrak{g}_x
    \end{align*}
    is given by the natural inclusion $F_z \subset \mathfrak{g}_x$ by Lemma~\ref{fib:F}. 
    In particular, it is injective. 

    The map 
     \begin{align*}
        F_z \stackrel{u|_{F_z}}{\to} \mathfrak{g}_{\overline{y}} \subset \mathfrak{g}_y
    \end{align*}
    is given by the map $\mathfrak{g}_x \to \mathfrak{g}_y$ induced by $f$ restricted to $F_z$.  Therefore, if $f$ is nil-effective, we have 
    \begin{align*}
        v|_{F_z}u|_{F_z}^{-1}(\mathrm{Nilp}(\mathfrak{g}_{\overline{y}})) \subset \mathrm{Nilp}(\mathfrak{g}_{\overline{x}}).
    \end{align*}
    Therefore (i) holds. The proof of (ii) is similar.

\label{cor:nilp2}
(i) In Proposition~\ref{prop:pback}, assume in addition that $f$ (hence $\alpha$) is nil-effective. 
Then the functor (\ref{funct:pback}) restricts to a functor  
    \begin{align}\notag f^{\Omega!} \colon 
    \operatorname{L}_{\mathcal{N}}(\Omega_{\mathcal{Y}})_{\delta\otimes \omega_{\mathcal{Y}}^{1/2}} \to \operatorname{L}_{\mathcal{N}}(\Omega_{\mathcal{X}})_{f^{\ast}\delta \otimes \omega_{\mathcal{X}}^{1/2}}  
\end{align} 

(ii) In Theorem~\ref{thm:proj}, the functor (\ref{funct:Lpush}) restricts to a functor  
     \begin{align}\notag
        f^{\Omega}_{*} \colon 
    \operatorname{L}_{\mathcal{N}}(\Omega_{\mathcal{X}})_{f^{\ast}\delta\otimes \omega_{\mathcal{X}}^{1/2}} \to \operatorname{L}_{\mathcal{N}}(\Omega_{\mathcal{Y}})_{\delta \otimes \omega_{\mathcal{Y}}^{1/2}}. 
    \end{align}

Following~\cite{halpinstab}, a \textit{$\Theta$-stratum} is defined to be 
an open and 
closed substack 
$\mathcal{S} \subset \mathrm{Map}(\Theta, \mathcal{Y})$
such that the composition 
\begin{align*}
    \mathcal{S} \subset \mathrm{Map}(\Theta, \mathcal{Y}) 
   \stackrel{\mathrm{ev_1}}{\to} 
    \mathcal{Y}
\end{align*}
is a closed immersion.

For each $k\in \mathbb{R}$, we define 
\begin{align*}
\mathcal{W}(k) \subset \operatorname{Coh}(\mathcal{Y})
\end{align*}
to be the full subcategory of objects $\mathcal{E}$ such that the set of weights 
of $\mathcal{E}|_{\mathcal{Z}}$ satisfies 
\begin{align*}
    \mathrm{wt}(\mathcal{E}|_{\mathcal{Z}}) \subset 
    [k, k+n), \mbox{ where } \ n:=\mathrm{wt} \det N_{\mathcal{S}/\mathcal{Y}}^{\vee}|_{\mathcal{Z}}.
\end{align*}

\emph{(\cite{MR3895631, halp, HalpK32})}\label{thm:window}
Let $k_0=\lfloor k \rfloor \in \mathbb{Z}$ be the round-down of $k$. 
The functor (\ref{funct:up}) is fully-faithful on each $\operatorname{Coh}(\mathcal{Z})_i$, 
and there is a semiorthogonal decomposition 
    \begin{align*}
    &\operatorname{Coh}(\mathcal{Y})=\\
    &\langle\ldots, \Upsilon \operatorname{Coh}(\mathcal{Z})_{k_0-2}, \Upsilon \operatorname{Coh}(\mathcal{Z})_{k_0-1}, 
    \mathcal{W}(k), \Upsilon \operatorname{Coh}(\mathcal{Z})_{k_0}, \Upsilon \operatorname{Coh}(\mathcal{Z})_{k_0+1}, \ldots\rangle.
    \end{align*}
    Moreover, the following composition functor is an equivalence:
    \begin{align*}
        \mathcal{W}(k) \subset \operatorname{Coh}(\mathcal{Y}) \to \operatorname{Coh}(\mathcal{Y}^{\circ}).
    \end{align*}

\label{em:sym}
	The stacks $\mathcal{S}$ and $\mathcal{Z}$ are smooth, and 
	$\mathcal{Z}$ is symmetric. Moreover, we have the identity
	\begin{align}\label{sym:N}
		[N_{\mathcal{S}/\mathcal{Y}}]=[\mathbb{L}_{\mathcal{S}/\mathcal{Z}}] \in K(\mathcal{S}). 
		\end{align}
        Here $N_{\mathcal{S}/\mathcal{Y}}$ is the normal bundle of $\mathcal{S}$ in $\mathcal{Y}$.

	There is a semiorthogonal decomposition 
	\begin{align}\label{sod:S}
		\operatorname{Coh}(\mathcal{S})=\langle \cdots, \operatorname{Coh}(\mathcal{S})_{i-1}, \operatorname{Coh}(\mathcal{S})_{i}, \operatorname{Coh}(\mathcal{S})_{i+1}, \cdots \rangle
		\end{align}
	such that we have the equivalence 
    $q^{\ast} \colon \operatorname{Coh}(\mathcal{Z})_i \stackrel{\sim}{\to} \operatorname{Coh}(\mathcal{S})_i$, see~\cite[Proposition~1.1.2, Lemma~1.5.6]{HalpK32}. 
	In particular for any $E \in \operatorname{Coh}(\mathcal{S})$ and $i\in \mathbb{Z}$ there is a unique 
	distinguished triangle 
	\begin{align}\label{triangle:beta}
		\beta_{>i}(E) \to E \to \beta_{\leqslant i}(E)
		\end{align}
	such that we have 
    \begin{align*}\beta_{>i}(E) \in \langle \operatorname{Coh}(\mathcal{S})_j : j>i\rangle, \ 
	\beta_{\leqslant i}(E) \in \langle \operatorname{Coh}(\mathcal{S})_j : j\leqslant i\rangle.
    \end{align*}

		By~\cite[Lemma~1.3.2, Lemma~1.5.5]{HalpK32}, the distinguished triangles 
	\begin{align*}
		\beta_{>0}(\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}}) \to 
		\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}} \to \beta_{\leqslant 0}(\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}}), \ 
		\beta_0(\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}}) \to 
		\beta_{\leqslant 0}(\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}}) \to \beta_{<0}(\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}})
		\end{align*}
	are identified with 
	\begin{align}\label{tri:NL}
		N_{\mathcal{S}/\mathcal{Y}}^{\vee} \to \mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}} \to \mathbb{L}_{\mathcal{S}}, \ 
		q^{\ast}\mathbb{L}_{\mathcal{Z}} \to \mathbb{L}_{\mathcal{S}} \to \mathbb{L}_{\mathcal{S}/\mathcal{Z}}
		\end{align}
	respectively. 
    In particular, the cotangent complexes $\mathbb{L}_{\mathcal{S}}$ and $\mathbb{L}_{\mathcal{Z}}$ 
    are perfect with cohomological amplitude $[0, 1]$, hence $\mathcal{S}$ and $\mathcal{Z}$ 
    are smooth. 

    By the symmetric condition of $\mathcal{Y}$ 
    and the uniqueness of 
	the triangle (\ref{triangle:beta}), we have 
	\begin{align*}
		[\mathbb{L}_{\mathcal{S}/\mathcal{Z}}]=[\beta_{<0}(\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}})]=[\beta_{>0}(\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}})]^{\vee}=
		[N_{\mathcal{S}/\mathcal{Y}}]
		\end{align*}
	in $K(\mathcal{S})$. Similarly $\beta_0(\mathbb{L}_{\mathcal{Y}}|_{\mathcal{S}})$ is self-dual in $K(\mathcal{S})$, which implies that 
	$[\mathbb{L}_{\mathcal{Z}}]=[\mathbb{L}_{\mathcal{Z}}^{\vee}]$ in $K(\mathcal{Z})$, hence $\mathcal{Z}$ is symmetric.

\label{prop:functUp}
Let $\delta' \in \mathrm{Pic}(\mathcal{Z})_{\mathbb{R}}$ be given by 
\begin{align*}
		\delta'=\left(\delta \otimes (\det N_{\mathcal{S}/\mathcal{Y}})^{1/2}\right)|_{\mathcal{Z}}.
		\end{align*}
Then an object $A \in \operatorname{Coh}(\mathcal{Z})$ satisfies $\Upsilon(A) \in \operatorname{M}(\mathcal{Y})_{\delta}$ if and only if 
  $A \in \operatorname{M}(\mathcal{Z})_{\delta'}$. 
  In particular, the functor (\ref{funct:up})
	restricts to the fully-faithful functor 
	\begin{align}\label{restrict:Up}
		\Upsilon \colon \operatorname{M}(\mathcal{Z})_{\delta'} \hookrightarrow  \operatorname{M}(\mathcal{Y})_{\delta}. 
		\end{align}

Let $j$ be the open immersion 
\begin{align*}
    j \colon \mathcal{Y}^{\circ}:=\mathcal{Y} \setminus \mathcal{S} \hookrightarrow 
    \mathcal{Y}. 
\end{align*}

\label{conj:adjoint}
(i) 
The functor (\ref{funct:j}) admits a fully-faithful 
right adjoint
\begin{align*}
    j_{\ast} \colon \operatorname{M}(\mathcal{Y}^{\circ})_{\delta} \hookrightarrow \operatorname{M}(\mathcal{Y})_{\delta}
\end{align*}
such that we have the semiorthogonal decompositions 
\begin{align*}
    \operatorname{M}(\mathcal{Y})_{\delta}
    =\langle j_{\ast}(\operatorname{M}(\mathcal{Y}^{\circ})_{\delta}), \Upsilon(\operatorname{M}(\mathcal{Z})_{\delta'})\rangle. 
\end{align*}

(ii) 
The functor (\ref{funct:j}) admits a fully-faithful 
left adjoint
\begin{align*}
    j_{!} \colon \operatorname{M}(\mathcal{Y}^{\circ})_{\delta} \hookrightarrow \operatorname{M}(\mathcal{Y})_{\delta}
\end{align*}
such that we have the semiorthogonal decompositions 
\begin{align*}
    \operatorname{M}(\mathcal{Y})_{\delta}
    =\langle \Upsilon(\operatorname{M}(\mathcal{Z})_{\delta'}), j_{!}(\operatorname{M}(\mathcal{Y}^{\circ})_{\delta})
    \rangle. 
\end{align*}

\emph{(\cite[Corollary~3.35]{PTquiver})}\label{prop:QB:weight}
The category $\operatorname{M}(\mathcal{Y})_{\delta}$ is generated by $V_G(\chi) \otimes \mathcal{O}_{\mathcal{Y}}$ 
where $\chi \in M(T)$ is a dominant weight satisfying 
\begin{align}\label{poly:W}
\chi+\rho-\delta \in \mathbf{W}:=\frac{1}{2}[0, \beta] \subset M(T)_{\mathbb{R}}.
\end{align}
Here, $V_G(\chi)$ is the irreducible $G$-representation 
with highest weight $\chi$, $[0, \beta]$ is the Minkowski sum of $T$-weights of $Y$,
and $\rho$ is half the sum of positive roots.

We define $\mathcal{Y}_i$ to be 
\begin{align*}
    \mathcal{Y}_i :=\mathcal{Y} \setminus (\mathcal{S}_1 \sqcup \cdots \sqcup \mathcal{S}_{i-1}), 
\end{align*}
so that $\mathcal{S}_i \subset \mathcal{Y}_i$ is a $\Theta$-stratum of $\mathcal{Y}_i$.

\label{prop:ess}
The pull-back functors 
\begin{align*}
j^{\ast} \colon \operatorname{M}(\mathcal{Y})_{\delta} \to \operatorname{M}(\mathcal{Y}^{\mathrm{ss}})_{\delta}, \ 
  \operatorname{M}(\overline{\mathcal{Z}}_i)_{\delta_i} \to \operatorname{M}(\mathcal{Z}_i)_{\delta_i}
\end{align*}
are essentially surjective.

Let $\delta_i \in \mathrm{Pic}(\mathcal{Z}_i)_{\mathbb{R}}$ be defined by 
\begin{align*}
    \delta_i:=(\delta \otimes (\det N_{\mathcal{S}_i/\mathcal{Y}_i})^{1/2})|_{\mathcal{Z}_i}. 
\end{align*}
It is induced by the following $G^{\lambda_i}$-character
\begin{align*}
    \delta_i=\delta-\frac{1}{2}(Y^{\lambda_i>0} - \mathfrak{g}^{\lambda_i>0}) \in M(T)_{\mathbb{R}}^{W_i}. 
\end{align*}

We prove the proposition by the induction on $i$. 
The base case of $i=0$ is obvious. We
assume that the semiorthogonal decomposition
\begin{align}\label{sod:qb:ind}
\operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_j=
\langle \Upsilon_j^{\dag}(\operatorname{M}(\mathcal{Z}_j)_{\delta_j}), \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{j+1} \rangle
\end{align}
holds for all $j\leqslant i-1$, and show that (\ref{sod:qb}) holds. 

        By Theorem~\ref{thm:window} for GIT quotient stacks~\cite{MR3895631, halp}, 
        we have the semiorthogonal decomposition 
        \begin{align}\label{window}
        \mathcal{W}_i=\langle 
            \Upsilon_i^{\dag}\operatorname{Coh}(\mathcal{Z}_i)_{\leqslant m_i}, \mathcal{W}_{i+1}, \Upsilon_i^{\dag}\operatorname{Coh}(\mathcal{Z}_i)_{>m_i} \rangle. 
        \end{align}
        Here for an interval $I\subset \mathbb{R}$, we have denoted by 
        $\Upsilon_i^{\dag}\operatorname{Coh}(\mathcal{Z}_i)_I$ the subcategory generated by 
        $\Upsilon_i^{\dag}\operatorname{Coh}(\mathcal{Z}_i)_a$ for $a \in I$. 
        Since we have 
        \begin{align*}
            \operatorname{M}(\mathcal{Z}_i)_{\delta_i} \subset \operatorname{Coh}(\mathcal{Z}_i)_{m_i}
        \end{align*}
        the right-hand side of (\ref{sod:qb}) is semiorthogonal. 

        We next show that the right-hand side of (\ref{sod:qb}) is 
        contained in the left-hand side. 
        It is enough to show that the functor (\ref{up:dag}) restricts 
        to the functor 
        \begin{align}\label{rest:Updag}
            \Upsilon_i^{\dag} \colon \operatorname{M}(\mathcal{Z}_i)_{\delta_i} \to \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i. 
        \end{align}     
   We set 
\begin{align*}
    \overline{\mathcal{S}}_i:=Y^{\lambda_i\geqslant 0}/G^{\lambda_i \geqslant 0}, \ 
    \overline{\mathcal{Z}}_i:=Y^{\lambda_i}/G^{\lambda_i}. 
\end{align*}
Note that $\mathcal{S}_i$ and $\mathcal{Z}_i$ are open substacks of 
$\overline{\mathcal{S}}_i$, $\overline{\mathcal{Z}}_i$, respectively. 
We have the following diagram 
\begin{align}\notag
\xymatrix{
\mathcal{Z}_i \ar@<-0.3ex>@{^{(}->}[d] \ar@/^10pt/[r]&
\mathcal{S}_i \ar@<-0.3ex>@{^{(}->}[d] \ar[l]^-{q_i} \ar@<-0.3ex>@{^{(}->}[r]_-{p_i} &
\mathcal{Y}_i \ar@<-0.3ex>@{^{(}->}[d] \\
\overline{\mathcal{Z}}_i  \ar@/_10pt/[r]& \overline{\mathcal{S}}_i \ar[l]_-{\overline{q}_i} \ar[r]^-{\overline{p}_i} & \mathcal{Y}.
}
\end{align}
Here each vertical arrows are open immersions. 
Since $\overline{p}_i$ is proper, we 
have the following functor
\begin{align}\label{ov:up:dag}
        \overline{\Upsilon}_i=\overline{p}_{i\ast}\overline{q}_{i}^{\ast} \colon 
    \operatorname{Coh}(\overline{\mathcal{Z}}_i) \to \operatorname{Coh}(\mathcal{Y}). 
\end{align}
By Lemma~\ref{lem:QB:rest} below, the functor (\ref{ov:up:dag})
restricts to the functor 
\begin{align}\label{restrict:QBdag}
\overline{\Upsilon}_i \colon \operatorname{M}(\overline{\mathcal{Z}}_i)_{\delta_i} \to \operatorname{M}(\mathcal{Y})_{\delta}.     
\end{align}

For $\mathcal{E} \in \operatorname{M}(\mathcal{Z}_i)_{\delta_i}$, let $\overline{\mathcal{E}} \in \operatorname{M}(\overline{\mathcal{Z}}_i)_{\delta_i}$ be its lift 
which exists by Proposition~\ref{prop:ess}.
We consider the object 
\begin{align}\notag
\overline{\Upsilon}_i(\overline{\mathcal{E}}) \in \operatorname{M}(\mathcal{Y})_{\delta}.
\end{align}
By the induction hypothesis (\ref{sod:qb:ind}), we have the semiorthogonal decomposition 
\begin{align}\label{ind:tr}
    \operatorname{M}(\mathcal{Y})_{\delta}=\langle \Upsilon_1^{\dag}\operatorname{M}(\mathcal{Z}_1)_{\delta_1}, \ldots, 
    \Upsilon_{i-1}^{\dag} \operatorname{M}(\mathcal{Z}_{i-1})_{\delta_{i-1}}, \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i
    \rangle. 
\end{align}
Let $\mathrm{pr} \colon \operatorname{M}(\mathcal{Y})_{\delta} \to \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i$
be the projection with respect to the above semiorthogonal decomposition, and set 
\begin{align*}
    \mathcal{F}=\mathrm{pr}\overline{\Upsilon}_i(\overline{\mathcal{E}}) \in 
    \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i. 
\end{align*}
Let $\Phi_i$ be the equivalence (\ref{eq:Phii}). 
Then 
\begin{align*}
\Phi_i(\mathcal{F})=\mathcal{F}|_{\mathcal{Y}_i} \cong\overline{\Upsilon}_i(\overline{\mathcal{E}})|_{\mathcal{Y}_i}
\end{align*}
and it is isomorphic to 
$\Upsilon_i(\mathcal{E})$ by Lemma~\ref{lem:extend} below. 
By the equivalence \[\Phi_i \colon \mathcal{W}_i \stackrel{\sim}{\to} \operatorname{Coh}(\mathcal{Y}_i)\] in 
(\ref{eq:Phii}),
it follows that 
\begin{align*}
    \Upsilon_i^{\dag}(\mathcal{E})=\Phi_i^{-1}\Upsilon_i(\mathcal{E})=\mathcal{F}
    \in \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i. 
\end{align*}
Therefore the functor (\ref{up:dag}) restricts to the functor (\ref{rest:Updag}). 

Finally we prove that the left-hand side in (\ref{sod:qb}) is contained in the right 
hand side. In Lemma~\ref{lem:delta} below, we will construct a functor
\begin{align*}\Delta_i\colon \operatorname{M}(\mathcal{Y})_{\delta}\to 
\operatorname{M}(\overline{\mathcal{Z}}_i)_{\delta_i}
\end{align*}
with a natural transform $\operatorname{id} \to \overline{\Upsilon}_i \Delta_i$. 
For $\mathcal{E} \in \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i$, let 
\begin{align}\label{dist:E}
\mathcal{E} \to \overline{\Upsilon}_i \Delta_i(\mathcal{E})
\end{align}
be the natural morphism. 
Since $\overline{\Upsilon}_i \Delta_i(\mathcal{E}) \in \operatorname{M}(\mathcal{Y})_{\delta}$, 
by the induction hypothesis (\ref{ind:tr})
there is a distinguished triangle 
\begin{align*}
    \mathrm{pr}\overline{\Upsilon}_i\Delta_i(\mathcal{E}) \to \overline{\Upsilon}_i \Delta_i(\mathcal{E}) \to A
\end{align*}
such that 
\begin{align*}
    \mathrm{pr}\overline{\Upsilon}_i\Delta_i(\mathcal{E}) \in \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i, \ 
    A \in \langle \Upsilon_i^{\dag}\operatorname{M}(\mathcal{Z}_j)_{\delta_j} : 1\leqslant j\leqslant i-1  \rangle. 
\end{align*}
Since $\mathcal{E} \in \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i$, 
the 
composition 
\begin{align*}
    \mathcal{E} \to  \overline{\Upsilon}_i \Delta_i(\mathcal{E}) \to A
    \end{align*}
is a zero morphism by the semiorthogonal decomposition (\ref{ind:tr}). 

Therefore the morphism (\ref{dist:E}) factors through 
a morphism $\mathcal{E} \to \mathrm{pr}\overline{\Upsilon}_i \Delta_i(\mathcal{E})$. 
We take the distinguished triangle 
\begin{align}\label{tr:E'}
    \mathcal{E}' \to \mathcal{E} \to \mathrm{pr}\overline{\Upsilon}_i \Delta_i(\mathcal{E}). 
\end{align}
It is enough to show that 
\begin{align}\label{enough:show}
\mathcal{E}' \in \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{i+1}, \ \mathrm{pr}\overline{\Upsilon}_i \Delta_i(\mathcal{E})
\in \Upsilon_i^{\dag}\operatorname{M}(\mathcal{Z}_i)_{\delta_i}. 
\end{align}
We have 
\begin{align}\label{isom:Upsilon}
(\mathrm{pr}\overline{\Upsilon}_i \Delta_i(\mathcal{E}))|_{\mathcal{Y}_i} \cong 
(\overline{\Upsilon}_i \Delta_i(\mathcal{E}))|_{\mathcal{Y}_i} \cong \Upsilon_i(\Delta_i(\mathcal{E})|_{\mathcal{Z}_i})
\end{align}
where the last isomorphism follows from Lemma~\ref{lem:extend}. 
Then from the equivalence (\ref{eq:Phii}), we have 
\begin{align*}
   \mathrm{pr}\overline{\Upsilon}_i \Delta_i(\mathcal{E})\cong\Upsilon_i^{\dag}(\Delta_i(\mathcal{E})|_{\mathcal{Z}_i})
\in \Upsilon_i^{\dag}\operatorname{M}(\mathcal{Z}_i)_{\delta_i}.
\end{align*}
Therefore the second condition of (\ref{enough:show}) holds. 

As for the first condition of (\ref{enough:show}), we take the restriction of (\ref{tr:E'})
to $\mathcal{S}_i$ 
\begin{align*}
    \mathcal{E}'|_{\mathcal{S}_i} \to \mathcal{E}|_{\mathcal{S}_i} \to (\mathrm{pr}\overline{\Upsilon}_i \Delta_i(\mathcal{E}))|_{\mathcal{S}_i}
    \cong \Upsilon_i(\Delta_i(\mathcal{E})|_{\mathcal{Z}_i})|_{\mathcal{S}_i}. 
\end{align*}
Here the last isomorphism is due to (\ref{isom:Upsilon}). 
By unraveling the construction of $\Delta_i$ in Lemma~\ref{lem:delta}, the second arrow in the 
above triangle is identified with the canonical map 
\begin{align}\label{map:betam}
    \mathcal{E}|_{\mathcal{S}_i} \to p_i^{\ast}p_{i\ast}\beta_{m_i}(\mathcal{E}|_{\mathcal{S}_i})
\end{align}
obtained by taking the adjoint of (\ref{wt:trun}) and restricting to $\mathcal{S}_i$. 
As in the proof of Proposition~\ref{prop:functUp}, the 
objects in (\ref{map:betam}) have $\lambda_i$-weights in 
$[m_i, m_i+n_{\lambda_i}]$ on $\mathcal{Z}_i$, such that the weight $m_i$-part is an 
isomorphism. 
Therefore $\mathcal{E}'|_{\mathcal{Z}_i}$ has $\lambda_i$-weights contained in 
$(m_i, m_i+n_{\lambda_i}]$, which implies 
that $\mathcal{E}' \in \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{i+1}$.

\label{lem:delta}
There is a natural functor 
\begin{align*}
\Delta_i \colon \operatorname{M}(\mathcal{Y})_{\delta} \to \operatorname{M}(\overline{\mathcal{Z}}_i)_{\delta_i}
\end{align*}
with a natural transform $\operatorname{id} \to \overline{\Upsilon}_i \Delta_i$.

    Note that it is obvious that 
    \begin{align}\label{inc:obv}
\operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i \subset \operatorname{M}(\mathcal{W}_i)_{\delta}. 
    \end{align}
    Below we show the converse direction by the induction on 
    $i$. The base case is $i=k+1$, and in this case $\mathcal{Y}_{k+1}=\mathcal{Y}^{\mathrm{ss}}$. 
    We need to show that the restriction functor 
    \begin{align}\label{ess:0}
        \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{k+1} \to \operatorname{M}(\mathcal{Y}^{\ell\text{-ss}})_{\delta}
    \end{align}
    is essentially surjective. 

    We perturb $\delta$ and take 
    $\delta'=\delta \otimes \ell^{-\varepsilon}$ for $0<\varepsilon \ll 1$. 
    By Proposition~\ref{prop:ess}, the restriction functor 
    \begin{align}\notag
\operatorname{M}(\mathcal{Y})_{\delta'} \to \operatorname{M}(\mathcal{Y}^{\ell\text{-ss}})_{\delta'}=\operatorname{M}(\mathcal{Y}^{\ell\text{-ss}})_{\delta}
    \end{align}
    is essentially surjective. Here the 
    last identity holds since for any $\nu \colon B\mathbb{G}_m \to \mathcal{Y}^{\ell\text{-ss}}$ 
the weight of $\nu^{\ast}\ell$ is zero by the definition of $\ell$-semistability. 
On the other hand, since $\lambda_i$-weight of $\ell$ is strictly negative for each $i$, 
we have 
\begin{align*}
    \operatorname{M}(\mathcal{Y})_{\delta'} \subset \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{k+1}. 
\end{align*}
Therefore the functor (\ref{ess:0}) is essentially surjective. 

We take $i\leqslant k$, 
and by induction assume that
\begin{align}\label{ind:j}
    \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{j}=\operatorname{M}(\mathcal{W}_j)_{\delta}
\end{align}
for all $i<j\leqslant k+1$. 
In what follows, we take 
$\mathcal{E} \in \operatorname{M}(\mathcal{W}_i)_{\delta}$
and show that $\mathcal{E}\in \operatorname{M}(\mathcal{Y})_{\delta}\cap \mathcal{W}_i$. 
Note that we have the semiorthogonal decomposition, see (\ref{window})
\begin{align}\label{sod:W2}
    \mathcal{W}_i=\langle \Upsilon_i^{\dag} \operatorname{Coh}(\mathcal{Z}_i)_{\leqslant m_i}, \mathcal{W}_{i+1}, 
    \Upsilon_i^{\dag}\operatorname{Coh}(\mathcal{Z}_i)_{>m_i} \rangle. 
\end{align}
Let $\mathrm{pr} \colon \mathcal{W}_i \twoheadrightarrow \mathcal{W}_{i+1}$ be 
the projection with respect to the above semiorthogonal decomposition. 
We have the commutative diagram 
\begin{align}\notag
    \xymatrix{
\mathcal{W}_i \ar@{->>}[r]^-{\mathrm{pr}} \ar[d]_-{\Phi_i}^-{\sim} & \mathcal{W}_{i+1} 
\ar[d]^-{\Phi_{i+1}}_-{\sim} \\
\operatorname{Coh}(\mathcal{Y}_i) \ar@{->>}[r] & \operatorname{Coh}(\mathcal{Y}_{i+1})    
    }
\end{align}
where the bottom functor is the restriction functor. 
Since the latter functor sends $\operatorname{M}(\mathcal{Y}_i)_{\delta}$ to $\operatorname{M}(\mathcal{Y}_{i+1})_{\delta}$, 
the projection $\mathrm{pr}$ sends $\operatorname{M}(\mathcal{W}_i)_{\delta}$ to $\operatorname{M}(\mathcal{W}_{i+1})_{\delta}$. 

Moreover $\mathcal{E}|_{\mathcal{Z}_i}$ has $\lambda_i$-weights in $[m_i, m_i+n_{\lambda_i}]$ 
since $\mathcal{E} \in \operatorname{M}(\mathcal{W}_i)_{\delta}$. It follows that 
the semiorthogonal decomposition (\ref{sod:W2}) yields the distinguished 
triangle 
\begin{align}\label{dist:E''}
  \mathcal{E}' \to \mathcal{E} \to \mathcal{E}'', \ \mathcal{E}'=\mathrm{pr}(\mathcal{E}) \in \operatorname{M}(\mathcal{W}_{i+1})_{\delta}, \ \mathcal{E}'' \in \Upsilon_i^{\dag}\operatorname{Coh}(\mathcal{Z}_i)_{m_i}.   
\end{align}
By the induction hypothesis (\ref{ind:j}), we have 
\begin{align}\notag
   \mathcal{E}' \in \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{i+1}. 
\end{align}
In particular we have $\mathcal{E}' \in \operatorname{M}(\mathcal{W}_i)_{\delta}$ because 
\begin{align*}
   \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{i+1} \subset  \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{i}
   \subset \operatorname{M}(\mathcal{W}_i)_{\delta}. 
\end{align*}
The last inclusion is due to (\ref{inc:obv}). 
By the distinguished triangle (\ref{dist:E''}), it follows that 
$\mathcal{E}'' \in \operatorname{M}(\mathcal{W}_i)_{\delta}$. 

This implies that 
\begin{align*}
    \Phi_i(\mathcal{E}'') \in \Upsilon_i \operatorname{Coh}(\mathcal{Z}_i)_{m_i} \cap \operatorname{M}(\mathcal{Y}_i)_{\delta}=
    \Upsilon_i \operatorname{M}(\mathcal{Z}_i)_{\delta_i}
\end{align*}
where $\Phi_i$ is the equivalence (\ref{eq:Phii}) and the last identity is due to Proposition~\ref{prop:functUp}. 
Therefore $\mathcal{E}'' \in \Upsilon_i^{\dag}\operatorname{M}(\mathcal{Z}_i)_{\delta_i}$. 
By the distinguished triangle (\ref{dist:E''}),
we obtain 
\begin{align*}
    \mathcal{E} \in \langle \Upsilon_i^{\dag}\operatorname{M}(\mathcal{Z}_i)_{\delta_i}, \operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_{i+1}
    \rangle =\operatorname{M}(\mathcal{Y})_{\delta} \cap \mathcal{W}_i
\end{align*}
where the last identity is proved in Proposition~\ref{prop:sod:qb}. 
Therefore (\ref{ind:j}) also holds for $j=i$, and by induction 
we conclude the assertion.

We only prove Conjecture~\ref{conj:adjoint} (ii) 
for $\mathcal{S}_i \subset \mathcal{Y}_i$, as the proof for (i) is similar. 

	By Proposition~\ref{prop:sod:qb} and Proposition~\ref{prop:QBW}, we have the 
