    \begin{align*}
        \operatorname{M}(\mathcal{W}_i)_{\delta}=\langle \Upsilon_i^{\dag}\operatorname{M}(\mathcal{Z}_i)_{\delta_i},  \operatorname{M}(\mathcal{W}_{i+1})_{\delta} \rangle. 
    \end{align*}
    By applying the functor $\Phi_i$ in (\ref{eq:Phii}), we obtain 
	\begin{align*}
		\operatorname{M}(\mathcal{Y}_{i})_{\delta}=\langle \Upsilon_i \operatorname{M}(\mathcal{Z}_i)_{\delta_i}, \Phi_i \operatorname{M}(\mathcal{W}_{i+1})_{\delta}\rangle. 
		\end{align*}

Let $j \colon \mathcal{Y}_{i+1} \hookrightarrow \mathcal{Y}_i$ be the open immersion.   
Then by the definition of $\operatorname{M}(\mathcal{W}_{i+1})_{\delta}$, 
the pull-back $j^{\ast} \colon \operatorname{Coh}(\mathcal{Y}_i) \to \operatorname{Coh}(\mathcal{Y}_{i+1})$ restricts to the 
equivalence 
\begin{align*}
	j^{\ast} \colon \Phi_i \operatorname{M}(\mathcal{W}_{i+1})_{\delta} \stackrel{\sim}{\to} 
	\operatorname{M}(\mathcal{Y}_{i+1})_{\delta}. 
	\end{align*}  
The functor 
\begin{align*}j_{!}=(j^{\ast})^{-1} \colon 
	\operatorname{M}(\mathcal{Y}_{i+1})_{\delta} \stackrel{\sim}{\to} \Phi_i \operatorname{M}(\mathcal{W}_{i+1})_{\delta}
	\subset \operatorname{M}(\mathcal{Y}_{i})_{\delta}
	\end{align*}
gives the fully-faithful left adjoint of $j^{\ast} \colon \operatorname{M}(\mathcal{Y}_{i})_{\delta} \to \operatorname{M}(\mathcal{Y}_{i+1})_{\delta}$ with semiorthogonal decomposition. 
\begin{align*}
		\operatorname{M}(\mathcal{Y}_{i})_{\delta}=\langle \Upsilon_i \operatorname{M}(\mathcal{Z}_i)_{\delta_i}, j_{!}\operatorname{M}(\mathcal{Y}_{i+1})_{\delta}\rangle. 
	\end{align*}
    Therefore Conjecture~\ref{conj:adjoint} (ii) holds for $\mathcal{S}_i \subset \mathcal{Y}_i$.

