\end{align}
which is a vector bundle on the smooth stack 
$\mathrm{Higgs}^L_G(\chi)_{\preceq \mu}$ in Lemma~\ref{lem:smooth}.

\label{lem:dtr}
There is a distinguished triangle 
\begin{align}\label{dtr:E}
\mathbb{T}_{\mathrm{Higgs}_G}|_{(E_G, \phi_G)}\to 
\mathbb{T}_{\mathrm{Higgs}_G^{L}}|_{(E_G, \phi_G^{L})} \to \Gamma(C, \mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L).
\end{align}

    The lemma follows by taking the cones of the following diagram 
    \begin{align*}
\xymatrix{
\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G))
\ar[r] \ar[d]_-{\operatorname{id}} & \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)\otimes \Omega_C) \ar[r] \ar[d] & \mathbb{T}_{\mathrm{Higgs}_G}|_{(E_G, \phi_G)}\ar[d] \\
\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)) \ar[r] &   \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)\otimes L)\ar[r] & \mathbb{T}_{\mathrm{Higgs}_G^{L}}|_{(E_G, \phi_G^{L})}. 
}        
    \end{align*}
    Here the middle vertical arrow is induced by $\Omega_C \hookrightarrow L=\Omega_C(D)$, whose cone is 
    $\Gamma(C, \mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)$.

For $\mu \in N(T)_{\mathbb{Q}+}$, consider the quasi-compact open substack 
\begin{align}\label{stack:U}
\mathcal{U} =\mathrm{Higgs}_G(\chi)_{\preceq \mu}
\subset \mathrm{Higgs}_G(\chi)
\end{align}
and 
an effective divisor $D$ on $C$ such that 
$\deg (D)>l(\mu)$ as in Lemma~\ref{lem:smooth}.
There is a closed immersion 
\begin{align}\label{emb:jU}
i \colon \mathcal{U} \stackrel{\iota_D}{\hookrightarrow} 
    \mathcal{U}^L:=\mathrm{Higgs}^L_G(\chi)_{\preceq \mu}
\end{align}
for $L=\Omega_C(D)$, where $\iota_D$ is defined as in (\ref{iota:DC}).
As in (\ref{deltaw}), we take 
\begin{align*}
    \delta=\delta_w \in \mathrm{Pic}(\mathrm{Bun}_G(\chi))_{\mathbb{Q}}.
\end{align*}
We often omit $w$ and just write it $\delta$. 
We also use the same symbol $\delta=\delta_w$ for its pull-back to 
$\mathrm{Higgs}^L_G(\chi)$. 
By Lemma~\ref{lem:emb}, we have the following description of $\operatorname{L}(\mathcal{U})_{w}$:

\label{defn:QB}
The subcategory
\begin{align}\label{def:QBH}
\operatorname{L}(\mathcal{U})_{\delta=\delta_w} \subset \operatorname{Coh}(\mathcal{U})
\end{align}
consists of objects $\mathcal{E}$ such that, for all $\nu \colon B\mathbb{G}_m \to \mathcal{U}$,
we have 
\begin{align}\notag
\mathrm{wt}(\nu^{\ast}i^{\ast}i_{\ast}\mathcal{E}) \subset 
\left[\frac{1}{2}c_1(\nu^{\ast}(\mathbb{L}_{\mathcal{V}^L}|_{\mathcal{U}})^{<0}), 
\frac{1}{2}c_1(\nu^{\ast}(\mathbb{L}_{\mathcal{V}^L}|_{\mathcal{U}})^{>0}) \right]
    +\mathrm{wt}(\nu^{\ast}\delta_w). 
\end{align}

Let $f$ be the function 
\begin{align}\label{funct:f}
    f \colon (\mathcal{V}^L)^{\vee} \to \mathbb{A}^1, \ f(x, v)=\langle s^L(x), v \rangle
\end{align}
where $s^L$ is the section (\ref{section:sL}), $x\in \mathcal{U}^L$ and 
$v\in (\mathcal{V}^L|_{x})^{\vee}$.

\label{lem:theta:crit2}
We have the identities 
\begin{align*}
    \mathcal{S}_{\mathrm{crit}}:=\pi_{\mathrm{crit}}^{-1}(\mathcal{S})=
    \mathrm{Crit}(f)\cap (\pi^L)^{-1}(\mathcal{S}^L)=\mathrm{Crit}(f) \cap \mathcal{S}_{\mathcal{V}}. 
\end{align*}
Here $\pi_{\mathrm{crit}}$ is given in the diagram (\ref{dia:crit}). 
Moreover $\mathcal{S}_{\mathrm{crit}}$ is a 
$\Theta$-stratum of $\mathrm{Crit}(f)$.

The first identity follows from the diagrams (\ref{dia:strata}), (\ref{dia:crit}). 
Below we prove the last identity. It is enough to show that 
\begin{align}\label{incl:crit}
\pi_{\mathrm{crit}}^{-1}(\mathcal{S}) \subset \mathrm{Crit}(f) \cap \mathcal{S}_{\mathcal{V}}. 
\end{align}

    For a point $p \in \mathcal{S} \subset \mathcal{U}$ corresponding 
    to a $G$-Higgs bundle $(E_G, \phi_G)$, the fiber of 
    $\pi_{\mathrm{crit}} \colon \mathrm{Crit}(f) \to \mathcal{U}$ at $p$ is 
    \begin{align*}
(\pi_{\mathrm{crit}})^{-1}(p)=(\mathbb{T}_{(E_G, \phi_G)}^1)^{\vee}=\mathbb{T}_{(E_G, \phi_G)}^{-1}
    \end{align*}
    by (\ref{M:shift}) and (\ref{MXcrit}). 
Note that we have 
\begin{align*}
    \mathbb{T}_{(E_G, \phi_G)}^{-1}=\operatorname{Ker}(H^0(\mathrm{Ad}_{\mathfrak{g}}(E_G)) \stackrel{[\phi_G, -]}{\to}
    H^0(\mathrm{Ad}_{\mathfrak{g}}(E_G)\otimes \Omega_C)).
\end{align*}

The fiber of $\pi^L \colon (\mathcal{V}^L)^{\vee} \to \mathcal{U}^L$ 
at $p \in \mathcal{U} \subset \mathcal{U}^L$ is 
\begin{align*}
(\pi^L)^{-1}(p)=\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)^{\vee}=
\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}).
\end{align*}
   The embedding $\mathrm{Crit}(f) \subset (\mathcal{V}^L)^{\vee}$ 
   at the fibers over $p$ is given by 
   the canonical map 
   \begin{align}\label{compose:Ad}
       \mathbb{T}_{(E_G, \phi_G)}^{-1} \hookrightarrow H^0(\mathrm{Ad}_{\mathfrak{g}}(E_G))
       \to \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}).
   \end{align}

   As $p\in \mathcal{S}$, the $G$-Higgs bundle $(E_G, \phi_G)$ admits a 
   HN filtration $(E_P, \phi_P)$. 
   Since $\mathcal{S}$ is a $\Theta$-stratum of $\mathcal{U}$, 
   we have 
   \begin{align*}
         \mathbb{T}_{(E_P, \phi_P)}^{-1} \stackrel{\cong}{\to} 
         \mathbb{T}_{(E_G, \phi_G)}^{-1}.
   \end{align*}
   Since the left-hand side is a subspace of $H^0(\mathrm{Ad}_{\mathfrak{p}}(E_P))$, 
   the above isomorphism implies that the image of the composition (\ref{compose:Ad})
   factors through $\Gamma(\mathrm{Ad}_{\mathfrak{p}}(E_P)|_{D})\subset \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D})$.
   Therefore from the definition of $\mathcal{S}_{\mathcal{V}}$, the inclusion (\ref{incl:crit}) holds.

We denote by 
\begin{align*}
    \mathcal{Z}_{\mathcal{V}}\subset \mathrm{Map}(B\mathbb{G}_m, (\mathcal{V}^L)^{\vee})
\end{align*}
the center of $\mathcal{S}_{\mathcal{V}}$.

\label{def:window:V}
We define 
\begin{align*}
    \mathcal{W}_{\mathcal{V}, \delta} \subset \operatorname{Coh}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})
\end{align*}
as the full subcategory consisting of objects $\mathcal{E}$ such that $\mathcal{E}|_{\mathcal{Z}_{\mathcal{V}}}$ satisfying 
\begin{align*}
    \mathrm{wt}(\mathcal{E}|_{\mathcal{Z}_{\mathcal{V}}}) \subset 
    \left(-\frac{1}{2}c_1 (N_{\mathcal{S}_{\mathcal{V}}/(\mathcal{V}^L)^{\vee}}^{\vee}|_{\mathcal{Z}_{\mathcal{V}}}), 
    \frac{1}{2}c_1 (N_{\mathcal{S}_{\mathcal{V}}/(\mathcal{V}^L)^{\vee}}^{\vee}|_{\mathcal{Z}_{\mathcal{V}}})
    \right]+c_1(\delta|_{\mathcal{Z}_{\mathcal{V}}}). 
\end{align*}
Here, $\mathrm{wt}(-)$ is the set of weights with respect to the decomposition (\ref{decom:Z}).

\label{rmk:nsv}
At each point in $z\in \mathcal{Z}_{\mathcal{V}}$, there is a canonical map $\nu \colon B\mathbb{G}_m \to \mathcal{Z}_{\mathcal{V}}$
with $\nu(0)=z$ 
by the definition of the center of a $\Theta$-stratum. 
Then we have 
\begin{align*}
    c_1 (N_{\mathcal{S}_{\mathcal{V}}/(\mathcal{V}^L)^{\vee}}^{\vee}|_{\mathcal{Z}_{\mathcal{V}}})=n_{(\mathcal{V}^L)^{\vee}, \nu} 
\end{align*}
where $n_{(\mathcal{V}^L)^{\vee}, \nu}$ is given by (\ref{def:nV}).

\label{prop:sod:V}
By replacing $\mathcal{U}^L$ with an open neighborhood of $\mathcal{U} \subset \mathcal{U}^L$ as in Remark~\ref{rmk:shrink} if necessary, 
there is a semiorthogonal decomposition 
\begin{align}\label{sod:V}
\operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta}=\langle \Upsilon_{\mathcal{V}} (\operatorname{M}_{\mathbb{G}_m}(\mathcal{Z}_{\mathcal{V}})_{\delta'}), \operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta} \cap 
\mathcal{W}_{\mathcal{V}, \delta}\rangle. 
\end{align}
Moreover the functor (\ref{funct:UpM}) is fully-faithful and 
(\ref{comp:func}) restricts to an equivalence 
\begin{align}\label{eq:QBV}
\Phi \colon 
\operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta} \cap \mathcal{W}_{\mathcal{V}, \delta} \stackrel{\sim}{\to}
\operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee}_{\circ})_{\delta}.     
\end{align}

We prove the proposition by reducing the problem to
the local case, which is proved in Theorem~\ref{thm:qstack}. 
A subtlety of this reduction is that the local model is not necessarily  a 
quotient of symmetric representations of a reductive group. Instead we modify 
the local model to make it a quotient of a symmetric representation, and apply Theorem~\ref{thm:qstack}.
Since the proof is long, we divide into some steps, and postpone some technical lemmas in 
Subsection~\ref{subsec:postpone}.

\begin{step}
An alternative statement for the semiorthogonal decomposition (\ref{sod:V}).
\end{step}
We first give an alternative statement for the semiorthogonal decomposition (\ref{sod:V}). 
By Theorem~\ref{thm:window}, 
there is a semiorthogonal decomposition 
\begin{align}\label{sod:VL}
    \operatorname{Coh}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})=\langle \Upsilon_{\mathcal{V}} \operatorname{Coh}_{\mathbb{G}_m}(\mathcal{Z}_{\mathcal{V}})_{\leqslant m}, \mathcal{W}_{\mathcal{V}, \delta}, \Upsilon_{\mathcal{V}} \operatorname{Coh}_{\mathbb{G}_m}(\mathcal{Z}_{\mathcal{V}})_{>m}\rangle
\end{align}
where $m$ is given by 
\begin{align*}
    m:= -\frac{1}{2} c_1 (N_{\mathcal{S}_{\mathcal{V}}/(\mathcal{V}^L)^{\vee}}^{\vee}|_{\mathcal{Z}_{\mathcal{V}}})+
    c_1(\delta|_{\mathcal{Z}_{\mathcal{V}}}). 
\end{align*}
Moreover, the functor $\Upsilon_{\mathcal{V}}$ is fully-faithful on each $\operatorname{Coh}_{\mathbb{G}_m}(\mathcal{Z}_{\mathcal{V}})_i$.
For an object $\mathcal{E} \in \operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta}$, 
the semiorthogonal decomposition (\ref{sod:VL}) yields 
a distinguished triangle 
\begin{align}\label{show:tri}
    \mathcal{E}'' \to \mathcal{E} \to \mathcal{E}', \ 
    \mathcal{E}' \in \Upsilon_{\mathcal{V}} \operatorname{Coh}_{\mathbb{G}_m}(\mathcal{Z}_{\mathcal{V}})_{m}, \ \mathcal{E}'' \in \mathcal{W}_{\mathcal{V}, \delta}. 
\end{align}

Therefore, it is enough to show that 
\begin{align}\label{ets:E}
\mathcal{E}' \in \Upsilon_{\mathcal{V}} \operatorname{M}_{\mathbb{G}_m}(\mathcal{Z}_{\mathcal{V}})_{\delta'}, \ \mathcal{E}'' \in \mathcal{W}_{\mathcal{V}, \delta} \cap \operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta}.     
\end{align}
It is also enough to show the second condition of (\ref{ets:E}), since then 
we have $\mathcal{E}' \in \operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta}$, 
and the first condition follows from Proposition~\ref{prop:functUp}. 
\begin{step}
    Reduction of (\ref{ets:E}) to the local case. 
\end{step}
Note that each point of $\mathcal{S}$ is obtained as a small deformation of a point $z \in \mathcal{S}$, 
given by the image of a closed point $z'\in\mathcal{Z}$ under the natural map $\mathcal{Z} \to \mathcal{S}$
in the diagram (\ref{derived:theta}). 
It 
corresponds to a $G$-Higgs bundle of the form
\begin{align}\label{deg:E}
(E_G, \phi_G)=(E_M, \phi_M)\times^M G
\end{align}
where $(E_M, \phi_M)$ is a polystable $M$-Higgs bundle, i.e. a
closed point of the stack $\mathrm{Higgs}_M(\chi_M)^{\mathrm{ss}}$ where $\chi_M\in \pi_1(M)$ 
is as in (\ref{center:Z}). The point $z$ corresponds to $(E_G, \phi_G)$ and $z'$ 
corresponds to $(E_M, \phi_M)$.
Let 
\begin{align*}
(E_G, \phi_G^{L})=\iota_D(E_G, \phi_G)
\end{align*}
be the corresponding $L$-twisted $G$-Higgs bundle by the map (\ref{iota:D}). 

We set 
    $\mathbf{E}:=\mathbb{T}^0_{(E_G, \phi_G^{L})}$ and 
\begin{align*}
    \mathbf{V}:= \mathbf{E}\oplus \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)^{\vee}=
    \mathbf{E}\oplus \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}).
\end{align*}
We regard $\mathbf{V}$ as a vector bundle over $\mathbf{E}$ by the natural 
projection. 

Let $G_E$ be the reductive subgroup of $\mathrm{Aut}(E_G, \phi_G)$ given by 
\begin{align*}
G_E :=\operatorname{Aut}(E_M, \phi_M) \subset \mathrm{Aut}(E_G, \phi_G)=\mathrm{Aut}(E_G, \phi_G^{L}).
\end{align*}
Let $G_E$ acts on $\mathbf{E}$ by conjugation. 
There is a smooth map (which follows from~\cite[Theorem~1.1]{AHRLuna})
\begin{align*}
    \widehat{\mathbf{E}}/G_E \to \mathcal{U}^L, \ 0 \mapsto \iota_D(z). 
\end{align*}
Here $\widehat{\mathbf{E}}$ is the pull-back of $\mathbf{E}$ under the 
formal completion 
\begin{align}\label{formal:comp}
    \operatorname{Spec} \widehat{\mathcal{O}}_{\mathbf{E}/\!\!/ G_E}
    \to  \operatorname{Spec} \mathcal{O}_{\mathbf{E}/\!\!/ G_E}.
\end{align}

Below we use the notation $\widehat{(-)}$ to denote the pull-back under 
the above morphism. 
Then we have 
\begin{align*}
    \widehat{\mathbf{V}}/G_E=(\mathcal{V}^L)^{\vee}\times_{\mathcal{U}^L}(\widehat{\mathbf{E}}/G_E). 
\end{align*}
\begin{step}
    Modification to the self-dual representation. 
\end{step}
The $G_E$-representation $\mathbf{V}$ is not necessarily self-dual, 
so we modify it to make it self-dual. 
By the distinguished triangle (\ref{dtr:E}), we have the 
morphism 
\begin{align*}
    \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L) \twoheadrightarrow \mathbb{T}^{1}_{(E_G, \phi_G)}
\end{align*}
which is surjective by $\mathbb{T}^1_{(E_G, \phi_G^{L})}=0$. 
By taking its dual, we obtain the following diagram of $G_E$-representations
\begin{align*}
    \xymatrix{
    \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}) \ar@{.>}[rd]^-{\eta}& \\
    \mathbb{T}^{-1}_{(E_G, \phi_G)} \ar@{->>}[r]\ar@<-0.3ex>@{^{(}->}[u] & \mathbb{T}^{-1}_{(E_G, \phi_G)}/\mathbb{T}^{-1}_{(E_M, \phi_M)}.
    }
\end{align*}
Since $G_E$ is reductive, 
there is a 
dotted arrow $\eta$ which is a surjective morphism of $G_E$-representations. 
Let $\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D})_0$ be the kernel of $\eta$ 
\begin{align*}
\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D})_0 :=\operatorname{Ker}(\eta\colon  \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}) \twoheadrightarrow
\mathbb{T}^{-1}_{(E_G, \phi_G)}/\mathbb{T}^{-1}_{(E_M, \phi_M)}
).
\end{align*}
We set 
\begin{align*}
\mathbf{V}_0 :=\mathbf{E} \oplus \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D})_0. 
\end{align*}
It is a sub $G_E$-representation of $\mathbf{V}$ and self-dual by Lemma~\ref{lem:symW} below.

Then we obtain the following commutative diagram 
\begin{align}\label{dia:VE}
\xymatrix{
\widehat{\mathbf{V}}_0/G_E \ar@<-0.3ex>@{^{(}->}[r]  \ar@/^15pt/[rr]^-{g}\ar[d] & \widehat{\mathbf{V}}/G_E \ar[d] \ar[r] & (\mathcal{V}^L)^{\vee} \ar[d] \\
\widehat{\mathbf{E}}/G_E \ar@{=}[r] & \widehat{\mathbf{E}}/G_E \ar[r] & \mathcal{U}^L. 
}
\end{align}
Recall that $z\in \mathcal{S}$ corresponds to $(E_G, \phi_G)$ and $z'\in \mathcal{Z}'$ 
corresponds to $(E_M, \phi_M)$ in (\ref{deg:E}). 
The canonical map $\nu \colon \mathbb{G}_m \to \mathcal{U}$ associated with $z'$ is given by 
$\nu(0)=z$ and 
a one-parameter subgroup 
\begin{align}\label{lambda:E}
\lambda \colon \mathbb{G}_m \to G_E \subset 
\mathrm{Aut}(E_G, \phi_G), \ G_E=\operatorname{Aut}(E_G, \phi_G)^{\lambda}.
\end{align}

Then we have the commutative diagram 
\begin{align}\label{dia:WG}
\xymatrix{
\widehat{\mathbf{V}}_0^{\lambda}/G_E \ar@<-0.3ex>@{^{(}->}[r]^-{\cong} & \widehat{\mathbf{V}}^{\lambda}/G_E 
\ar[r]^-{g^{\lambda}} & \mathcal{Z}_{\mathcal{V}} \\
\widehat{\mathbf{V}}_0^{\lambda \geqslant 0}/G_E \ar[u]^-{q_0}  \ar@<-0.3ex>@{^{(}->}[d]_-{p_0}  \ar@<-0.3ex>@{^{(}->}[r]  \ar@{}[rd]|\square & \widehat{\mathbf{V}}^{\lambda \geqslant 0}/G_E \ar[r] \ar[u]\ar@<-0.3ex>@{^{(}->}[d]  \ar@{}[rd]|\square& \mathcal{S}_{\mathcal{V}} \ar@<-0.3ex>@{^{(}->}[d] \ar[u] \\
\widehat{\mathbf{V}}_0/G_E \ar@<-0.3ex>@{^{(}->}[r] \ar@/_15pt/[rr]_-{g}& \widehat{\mathbf{V}}/G_E \ar[r] & (\mathcal{V}^L)^{\vee}. }    
\end{align}
Here we note that $G_E=G_E^{\lambda \geqslant 0}=G_E^{\lambda}$. As we will prove in Lemma~\ref{lem:cart0}, the bottom 
squares are derived Cartesians and the top left arrow is an isomorphism. 
\begin{step}
Proof of (\ref{sod:V}) via application of the results in Section~\ref{sec:magic}.
\end{step}
By taking the pull-back of the triangle (\ref{show:tri}) by the map $g$ in (\ref{dia:VE}), 
we have the distinguished triangle in $\operatorname{Coh}(\widehat{\mathbf{V}}_0/G_E)$
\begin{align}\label{tr:gE}
    g^{\ast}\mathcal{E}'' \to g^{\ast}\mathcal{E} \to g^{\ast}\mathcal{E}'. 
\end{align}
By Lemma~\ref{lem:neq} and the assumption $\mathcal{E} \in \operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta}$, 
we conclude
\begin{align*}
    g^{\ast}\mathcal{E} \in \operatorname{M}(\widehat{\mathbf{V}}_0/G_E)_{g^{\ast}\delta}.
\end{align*}
The distinguished triangle (\ref{tr:gE}) is the one 
induced by a $\Theta$-stratum
\[\widehat{\mathbf{V}}_0^{\lambda \geqslant 0}/G_E \hookrightarrow \widehat{\mathbf{V}}_0/G_E\]
as in (\ref{show:tri}). 
Namely, let  
\begin{align*}
    \mathcal{W}_{\widehat{\mathbf{V}}_0, g^{\ast}\delta} \subset \operatorname{Coh}(\widehat{\mathbf{V}}_0/G_E)
\end{align*}
be the window subcategory for the $\Theta$-stratum 
$\widehat{\mathbf{V}}_0^{\lambda\geqslant 0}/G_E \hookrightarrow \widehat{\mathbf{V}}_0/G_E$, 
consisting of objects whose $\lambda$-weights on 
$\widehat{\mathbf{V}}_0^{\lambda}/G_E$ are contained in 
\begin{align*}
\left(-\frac{1}{2}n_{\mathbf{V}_0/G, \lambda}, 
\frac{1}{2}n_{\mathbf{V}_0/G, \lambda}\right]+\langle \delta, \lambda\rangle. 
\end{align*}
Here we have identified $\lambda$ with a map 
$B\mathbb{G}_m \to \mathbf{V}_0/G_E$ 
to the origin given by 
$\lambda \colon \mathbb{G}_m\to G_E=\mathrm{Aut}(0)$. 
Then we have 
\begin{align}\label{cond:g*E}
    g^{\ast}\mathcal{E}' \in \Upsilon_0 \operatorname{Coh}(\widehat{\mathbf{V}}_0^{\lambda}/G_E)_m, \ 
    g^{\ast}\mathcal{E}'' \in \mathcal{W}_{\widehat{\mathbf{V}}_0, g^{\ast}\delta}
\end{align}
where $\Upsilon_0=p_{0\ast}q_0^{\ast}$ in the diagram (\ref{dia:WG}). 
The first condition follows from Lemma~\ref{lem:cart0} together with the base change, 
and the second condition follows from the diagram (\ref{dia:WG}) together with 
Lemma~\ref{lem:neq}. 

We apply Proposition~\ref{prop:QBW} to the stack $\widehat{\mathbf{V}}_0/G_E$, 
which is possible since $\mathbf{V}_0$ is a self-dual representation of the reductive group $G_E$
\footnote{The setting here is slightly different from Proposition~\ref{prop:QBW} as we 
are taking base-change of the formal completion (\ref{formal:comp}). It is straightforward 
to check that the same argument works in this setting.}. 
Then we conclude that 
\begin{align}\label{ets:E2}
    g^{\ast}\mathcal{E}' \in \Upsilon_0 \operatorname{M}(\widehat{\mathbf{V}}_0^{\lambda}/G_E)_{g^{\lambda\ast}\delta'}, \ 
    g^{\ast}\mathcal{E}'' \in \operatorname{M}(\widehat{\mathbf{V}}_0/G_E)_{g^{\ast}\delta}. 
\end{align}

Indeed let $(\widehat{\mathbf{V}}_0)_{\circ}=\widehat{\mathbf{V}}_0 \setminus \widehat{\mathbf{V}}_0^{\lambda \geqslant 0}$. Then we have 
\begin{align*}
    g^{*}\mathcal{E}''|_{(\widehat{\mathbf{V}}_0)_{\circ}/G_E} =g^{*}\mathcal{E}|_{(\widehat{\mathbf{V}}_0)_{\circ}/G_E} \in \operatorname{M}((\widehat{\mathbf{V}}_0)_{\circ}/G_E)_{g^{\ast}\delta}.
\end{align*}

Therefore by the second condition in (\ref{cond:g*E}) and Proposition~\ref{prop:QBW}, the object $g^* \mathcal{E}''$ satisfies the second condition in (\ref{ets:E2}). 
Then by Proposition~\ref{prop:functUp}, we have 
\begin{align*}
     g^{\ast}\mathcal{E}'\in &\Upsilon_0 \operatorname{Coh}(\widehat{\mathbf{V}}_0^{\lambda}/G_E)_m \cap 
     \operatorname{M}(\widehat{\mathbf{V}}_0/G_E)_{g^{\ast}\delta} \\
     &=\Upsilon_0 \operatorname{M}(\widehat{\mathbf{V}}_0^{\lambda}/G_E)_{g^{\lambda\ast}\delta'}.
\end{align*}
Therefore (\ref{ets:E2}) holds. 
By the distinguished triangle (\ref{show:tri}), we also have 
\begin{align*}
\mathcal{E}''|_{(\mathcal{V}^L)^{\vee}_{\circ}} \cong \mathcal{E}|_{(\mathcal{V}^L)^{\vee}_{\circ}} 
\in \operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)_{\circ}^{\vee})_{\delta}.     
\end{align*}
By applying Lemma~\ref{lem:pullback} below,  
the second condition of (\ref{ets:E2}) implies the second 
condition of (\ref{ets:E}), therefore we obtain the semiorthogonal 
decomposition (\ref{sod:V}). 

\begin{step}
Proof of the equivalence (\ref{eq:QBV}).
\end{step}
Finally we show the equivalence (\ref{eq:QBV}).
Let $\Phi$ be the equivalence (\ref{comp:func}).
Obviously we have the inclusion 
\begin{align}\label{incl:phi}
\operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee})_{\delta} \cap \mathcal{W}_{\mathcal{V}, \delta}
\subset \Phi^{-1} \operatorname{M}_{\mathbb{G}_m}((\mathcal{V}^L)^{\vee}_{\circ})_{\delta}.   
\end{align}
It is enough to show that the above inclusion is an equivalence. 
For an object $A$ in the right-hand side of (\ref{incl:phi}), 
by the diagram (\ref{dia:WG}) and Proposition~\ref{prop:QBW}, 
we have 
\begin{align*}
    g^{\ast}A \in
    \operatorname{M}(\mathcal{W}_{\widehat{\mathbf{V}}_0, g^{\ast}\delta})=
    \operatorname{M}(\widehat{\mathbf{V}}_0/G_E)_{g^{\ast}\delta} \cap 
    \mathcal{W}_{\widehat{\mathbf{V}}_0, g^{*}\delta}.
\end{align*}
Therefore the object $A$ lies in the left-hand 
side of (\ref{incl:phi}) by Lemma~\ref{lem:pullback}.

\label{prop:sod:KZ}
For the open immersion $j \colon \mathcal{U}_{\circ} \hookrightarrow \mathcal{U}$, 
its pull-back 
\[j^{\ast} \colon \operatorname{L}(\mathcal{U})_{\delta} \to \operatorname{L}(\mathcal{U}_{\circ})_{\delta}\]
admits a fully-faithful left adjoint 
\begin{align}\label{j!}
	j_{!} \colon \operatorname{L}(\mathcal{U}_{\circ})_{\delta} \hookrightarrow \operatorname{L}(\mathcal{U})_{\delta}	
\end{align}
and the semiorthogonal decomposition 
	\begin{align}\label{sod:qbud}
		\operatorname{L}(\mathcal{U})_{\delta}=
		\langle \Upsilon_{\mathcal{U}} \operatorname{L}(\mathcal{Z})_{\delta'}, j_{!}\operatorname{L}(\mathcal{U}_{\circ})_{\delta} \rangle. 
		\end{align}
	Here $\delta'=\delta \otimes (\det \mathbb{L}_{p})^{1/2}|_{\mathcal{Z}}$, and 
    the functor $\Upsilon_{\mathcal{U}}$ is fully-faithful on $\operatorname{L}(\mathcal{Z})_{\delta'}$.

By the Koszul equivalence in Theorem~\ref{thm:Kduality} 
associated with the diagram (\ref{dia:crit}), we have an equivalence
\begin{align*}
    \Psi \colon \operatorname{Coh}(\mathcal{U}) \stackrel{\sim}{\to} \mathrm{MF}^{\mathrm{gr}}((\mathcal{V}^L)^{\vee}, f). 
\end{align*}
By Proposition~\ref{prop:comparemagic}, it restricts to an equivalence
\begin{align*}
\Psi \colon \operatorname{L}(\mathcal{U})_{\delta}\stackrel{\sim}{\to}
\mathrm{MF}^{\mathrm{gr}}(\operatorname{M}((\mathcal{V}^L)^{\vee})_{\delta\otimes (\omega_{\mathcal{U}^L})^{1/2}}, f). 
