\operatorname{L}(\mathcal{U})_{\delta} \ar[r]^-{\Psi}_-{\sim} \ar[d]_-{j^{\ast}} & 	\mathrm{MF}^{\mathrm{gr}}(\operatorname{M}(\mathcal{V}^L)^{\vee})_{\delta\otimes (\omega_{\mathcal{U}^L})^{1/2}}, f) \ar[d]^-{j_{\mathcal{V}}^{\ast}} \\
