=\\ \notag
&\left\langle \Upsilon_{\mathcal{V}} \mathrm{MF}^{\mathrm{gr}}(\operatorname{M}(\mathcal{Z}_{\mathcal{V}})_{\delta'\otimes (\omega_{\mathcal{U}^L})^{1/2}}), f_{\mathcal{Z}}), 
j_{\mathcal{V}!}  \mathrm{MF}^{\mathrm{gr}}(\operatorname{M}(\mathcal{V}^L)^{\vee}_{\circ})_{\delta\otimes (\omega_{\mathcal{U}^L})^{1/2}}, f) \right\rangle. 	
