W_x^{\mu} :=
    \otimes (\mathcal{V}_{x}^{\mu})^{\vee} \colon \operatorname{Coh}(\mathrm{Higgs}_{^{L}G}(w)^{\mathrm{ss}})_{-\chi}
    \to \operatorname{Coh}(\mathrm{Higgs}_{^{L}G}(w)^{\mathrm{ss}})_{-\chi-\overline{\mu}}.
