\label{prop:Hecke:sod}
The right action of an object in $A\in \mathbb{T}(m)_0$ restricted to a semiorthogonal summand
in (\ref{sod:GLr}) gives a functor
    \begin{align*}
    (-)\ast A \colon 
\bigotimes_{i=1}^k \mathbb{T}_{\operatorname{GL}_{r_i}}(\chi_i)_{w_i} 
\to \left\langle \bigotimes_{i=1}^{k'} \mathbb{T}_{\operatorname{GL}_{r_i'}}(\chi_i')_{w_i'}\right\rangle.
    \end{align*}
    Here the right-hand side is after all partitions 
    $(r_1', \chi_1', w_1')+\cdots+(r_{k'}', \chi_k', w_k')=(r, \chi+m, w)$ such that 
    \begin{align*}
        \frac{\chi_1'}{r_1'}>\cdots>\frac{\chi_{k'}}{r_k'}, \
        \frac{\chi_1'}{r_1'}\geqslant \frac{\chi_1}{r_1}\geqslant\frac{\chi_1'-m}{r_1'}, \
        \frac{w_i'}{r_i'}=\frac{w}{r}.
    \end{align*}

As in the proof of Lemma~\ref{lem:support}, for an exact sequence in $\operatorname{Coh}(S)$
\begin{align*}
    0\to E\to E'\to R \to 0
\end{align*}
where $R$ is zero-dimensional and $E, E'$ pure one-dimensional with compact supports, 
we have 
\begin{align*}
    \mu^{\mathrm{max}}(E') \leqslant \mu^{\mathrm{max}}(E) \leqslant \mu^{\mathrm{max}}(E')-\frac{m}{r_1'}
\end{align*}
Here $r_1'$ is the rank of the first HN factor of $E'$. Then the Proposition holds 
by the same argument in the proof of Proposition~\ref{prop:hecke2}.

\label{exam:Hecke}
We describe how Wilson and Hecke operators interact with the semiorthogonal decompositions in Theorem~\ref{thm:PThiggs}, Theorem~\ref{thm:mainLG} in a simple example. 
    We consider the case $g(C)=0$, i.e. $C=\mathbb{P}^1$, and $G=\operatorname{GL}_2$. 
    We take the minuscule coweight $\mu$ to be $\mu=(1, 0)$. 

    In this case, 
    we have 
\begin{align*}
    \operatorname{Coh}(\mathrm{Higgs}_{\operatorname{GL}_2}(0)^{\mathrm{ss}})_0 &=\operatorname{Coh}^{{\mathbin{\mkern-6mu\fatslash}}}(\mathfrak{gl}_2/\operatorname{GL}_2)_0 \\
    &=\langle \mathbb{T}_{\mathbb{G}_m}(0)_{-w}\otimes \mathbb{T}_{\mathbb{G}_m}(0)_w, \mathbb{T}_{\operatorname{GL}_2}(0)_0 : w>0\rangle, \\
    \operatorname{Coh}(\mathrm{Higgs}_{\operatorname{GL}_2}(0)^{\mathrm{ss}})_{-1} &=\operatorname{Coh}^{{\mathbin{\mkern-6mu\fatslash}}}(\mathfrak{gl}_2/\operatorname{GL}_2)_{-1} \\
    &=\langle \mathbb{T}_{\mathbb{G}_m}(0)_{-w-1}\otimes \mathbb{T}_{\mathbb{G}_m}(0)_w : w\geqslant 0\rangle.
\end{align*}

Let $V$ be a two-dimensional vector space. Then $\mathbb{T}_{\operatorname{GL}_2}(0)_0$ is generated by 
\begin{align*}E_0:=\mathcal{O}_{\mathfrak{gl}_2/\operatorname{GL}_2}\in \mathbb{T}_{\operatorname{GL}_2}(0)_0.
\end{align*}
Also 
$\mathbb{T}_{\mathbb{G}_m}(0)\otimes \mathbb{T}_{\mathbb{G}_m}(-1)$ is generated by 
\begin{align*}
F_0:=\mathcal{O}_{\mathfrak{gl}_1/\mathbb{G}_m} \otimes\mathcal{O}_{\mathfrak{gl}_1/\mathbb{G}_m}(-1) =
V^{\vee}\otimes \mathcal{O}_{\mathfrak{gl}_2/\operatorname{GL}_2}.
\end{align*}
Moreover 
    $ \mathbb{T}_{\mathbb{G}_m}(0)_{-w}\otimes \mathbb{T}_{\mathbb{G}_m}(0)_w$ for $w>0$ is generated by a two-term complex of the form 
    \begin{align*}
        E_w:=&\left(\mathrm{Sym}^{2w-2}(V) \otimes (\det V)^{1-w} \otimes  \mathcal{O}_{\mathfrak{gl}_2/\operatorname{GL}_2}\right. \\
        &\left.\to \mathrm{Sym}^{2w}(V)\otimes (\det V)^{-w} \otimes  \mathcal{O}_{\mathfrak{gl}_2/\operatorname{GL}_2}\right).
    \end{align*}
    Similarly $\mathbb{T}_{\mathbb{G}_m}(0)_{-w-1}\otimes \mathbb{T}_{\mathbb{G}_m}(0)_w$ for $w>0$ is generated by a two-term complex of the form 
    \begin{align*}
        F_w:=&\left(\mathrm{Sym}^{2w-1}(V)\otimes (\det V)^{-w} \otimes  \mathcal{O}_{\mathfrak{gl}_2/\operatorname{GL}_2} \right. \\
        &\left.\to \mathrm{Sym}^{2w+1}(V)\otimes (\det V)^{-1-w} \otimes  \mathcal{O}_{\mathfrak{gl}_2/\operatorname{GL}_2}\right).
    \end{align*}

Therefore we have 
\begin{align*}
    &K(\operatorname{Coh}(\mathrm{Higgs}_{\operatorname{GL}_2}(0)^{\mathrm{ss}})_0)=\bigoplus_{w\geqslant 0}\mathbb{Z}[E_w], \\ 
    & K(\operatorname{Coh}(\mathrm{Higgs}_{\operatorname{GL}_2}(0)^{\mathrm{ss}})_{-1})=\bigoplus_{w\geqslant 0}\mathbb{Z}[F_w].
\end{align*}
By the decomposition 
\begin{align*}
    \mathrm{Sym}(V)\otimes V^{\vee}=(\mathrm{Sym}^{m+1}(V)\otimes \det V^{\vee}) \oplus \mathrm{Sym}^{m-1}(V)
\end{align*}
the operator $W_x^{\mu}$ in K-theory is given by 
\begin{align}\label{wilson:GL2}
    [E_0]\mapsto [F_0], \ [E_w] \mapsto [F_w]+[F_{w+1}], \ (w>0).
\end{align}

In the automorphic side, we have the semiorthogonal decompositions 
\begin{align*}
    \operatorname{L}(\mathrm{Higgs}_{\operatorname{GL}_2}(0))_0 
    &=\langle \mathbb{T}_{\mathbb{G}_m}(\chi)_{0}\otimes \mathbb{T}_{\mathbb{G}_m}(-\chi)_0, \mathbb{T}_{\operatorname{GL}_2}(0)_0 : \chi>0\rangle, \\
    \operatorname{L}(\mathrm{Higgs}_{\operatorname{GL}_2}(1))_{0}
    &=\langle \mathbb{T}_{\mathbb{G}_m}(\chi+1)_{0}\otimes \mathbb{T}_{\mathbb{G}_m}(-\chi)_w : \chi\geqslant 0\rangle.
\end{align*}
By Proposition~\ref{prop:Hecke:sod}, the Hecke operator $H_x^{\mu}$ for $\mu=(1, 0)$ restricts to the functor
    \begin{align*}
        H_x^{\mu} \colon \mathbb{T}_{\operatorname{GL}_2}(0)_0 \to \mathbb{T}_{\mathbb{G}_m}(1)_0\otimes \mathbb{T}_{\mathbb{G}_m}(0)
        \end{align*}
        and for $\chi>0$, 
        \begin{align*}
            H_x^{\mu} \colon &
       \mathbb{T}_{\mathbb{G}_m}(\chi)_{0}\otimes \mathbb{T}_{\mathbb{G}_m}(-\chi)_0 \\
       &\to \langle \mathbb{T}_{\mathbb{G}_m}(\chi+1)_{0}\otimes \mathbb{T}_{\mathbb{G}_m}(-\chi)_0, 
       \mathbb{T}_{\mathbb{G}_m}(\chi)_{0}\otimes \mathbb{T}_{\mathbb{G}_m}(1-\chi)_0\rangle. 
    \end{align*}
    A simple geometric reason is that, for a vector bundle 
    $\mathcal{O}_{\mathbb{P}^1}(\chi)\oplus \mathcal{O}_{\mathbb{P}^1}(-\chi)$ on $\mathbb{P}^1$ and 
    an exact sequence 
    \begin{align*}
        0 \to \mathcal{O}_{\mathbb{P}^1}(\chi)\oplus \mathcal{O}_{\mathbb{P}^1}(-\chi) \to F \to \mathcal{O}_x \to 0
    \end{align*}
    for a vector bundle $F$ on $\mathbb{P}^1$, we have 
    \begin{align*}
    F\cong \begin{cases}
        \mathcal{O}_{\mathbb{P}^1}(1)\oplus \mathcal{O}_{\mathbb{P}^1}, & (\chi=0), \\
         \mathcal{O}_{\mathbb{P}^1}(\chi+1)\oplus \mathcal{O}_{\mathbb{P}^1}(-\chi), \mbox{ or }
         \mathcal{O}_{\mathbb{P}^1}(\chi)\oplus \mathcal{O}_{\mathbb{P}^1}(1-\chi), & (\chi>0).
        \end{cases}
    \end{align*}
    Therefore it is compatible with the computation of the Wilson operator (\ref{wilson:GL2}).

Let 
\begin{align*}
    \mathbb{H}_{\mathcal{N}} \subset \mathbb{H}, \ \operatorname{Ind} \mathbb{H}_{\mathcal{N}} \subset \operatorname{Ind} \mathbb{H}
\end{align*}
be the subcategories with nilpotent singular supports.

