\label{subsec:essurj}
The proof is the same as in~\cite[Proposition~3.22]{PTquiver} with some 
minor modifications. We only explain how to modify the arguments.

It is enough to show the essential surjectivity of 
\begin{align*}
    j^* \colon \operatorname{M}(\mathcal{Y})_{\delta} \to \operatorname{M}(\mathcal{Y}^{\ell\text{-ss}})_{\delta}
\end{align*}
as the essential surjectivity of the pullback \[\operatorname{M}(\overline{\mathcal{Z}}_i)_{\delta_i} \to 
\operatorname{M}(\mathcal{Z}_i)_{\delta}\] also follows from the above. 
Let $T \subset G$ be a maximal torus and $T' \subset T$ the 
subgroup of $t\in T$ which acts on $Y$ trivially. We have the 
decomposition 
\begin{align*}
    \operatorname{Coh}(\mathcal{Y})=\bigoplus_{w \in (T')^{\vee}}\operatorname{Coh}(\mathcal{Y})_{w}
\end{align*}
where $\operatorname{Coh}(\mathcal{Y})_{w}$ is the subcategory of $T'$-weights $w$. 
Let $M_{0, \mathbb{R}}$ be the kernel 
\begin{align*}
    M_{0, \mathbb{R}}:=\operatorname{Ker}(M(T)_{\mathbb{R}} \twoheadrightarrow M(T')_{\mathbb{R}}).
\end{align*}

Note that we may assume that $\ell \in M_{0, \mathbb{R}}$ as otherwise we have $\mathcal{Y}^{\ell\text{-ss}}=\emptyset$.
Then we have $\mathbf{W} \subset M_{0, \mathbb{R}}$ where 
$\mathbf{W}$ is the polytope in (\ref{poly:W}). 
Let $\lambda_1, \ldots, \lambda_m\in N(T)$ be anti-dominant cocharacters 
such that $\lambda_i^{\perp}$ give faces of $\mathbf{W}$. 
Let $W$ be the Weyl group of $G$.
Then we have the following generalization of~\cite[Lemma~3.16]{PTquiver}: 
\begin{lemma}\label{lem:magicgen}
    For $\ell\in M_{0, \mathbb{R}}$ and $\delta \in M(T)_{\mathbb{R}}^W$ with 
    $T'$-weight $w$, the category $\operatorname{Coh}(\mathcal{Y}^{\ell\text{-ss}})_w$ is generated by 
    $j^*(\operatorname{M}(\mathcal{Y})_{\delta})$ and objects of the form $m_{\lambda}(P)$
    where $P \in \operatorname{Coh}(\mathcal{Y}^{\lambda})_w$ is generated by $V_{G^{\lambda}}(\chi'')\otimes \mathcal{O}_{\mathcal{Y}^{\lambda}}$ such that 
    \begin{align}\label{ineq:chi''}
        \langle \lambda, \chi'' \rangle <-\frac{1}{2}\langle \lambda, \mathbb{L}_{\mathcal{Y}}^{\lambda>0}\rangle+\langle \lambda, \delta\rangle
    \end{align}
    and $\lambda \in \{\lambda_1, \ldots, \lambda_m\}$ such that $\langle \lambda, \ell \rangle=0$. Here $V_{G^{\lambda}}(\chi'')$ is the irreducible $G^{\lambda}$-representation with highest weight $\chi''$. The functor $m_{\lambda}$ is 
    the categorical Hall product $m_{\lambda}=p_{*}q^{*}$ for the diagram 
    \begin{align*}
        \mathcal{Y}^{\lambda} \stackrel{q}{\leftarrow} \mathcal{Y}^{\lambda \geqslant 0} \stackrel{p}{\to} \mathcal{Y}.
    \end{align*}
\end{lemma}
\begin{proof}
    The proof of~\cite[Lemma~3.16]{PTquiver} applies verbatim, 
    using the induction of the invariants $(r_{\chi}, p_{\chi})$ as in~\cite{SvdB}. 
    The relevant reference~\cite[Proposition~3.4]{hls} in loc. cit. is discussed 
    in the setting of the quotient stack $Y/G$. Consequently, it is applicable in our situation. 
\end{proof}

By Lemma~\ref{lem:magicgen}, it is enough to show the vanishing 
\begin{align}\label{vanish:Mres}
    \operatorname{Hom}(\operatorname{M}(\mathcal{Y}^{\ell\text{-ss}})_{\delta}, j^*(m_{\lambda}(P)))=0,
\end{align}
where $m_{\lambda}(P)$ is an object as in Lemma~\ref{lem:magicgen}, see the first part 
of the proof of~\cite[Proposition~3.22]{PTquiver}. 
By Lemma~\ref{lem:cart2} below, we have the following diagram 
\begin{align}\label{dia:semistable}
    \xymatrix{
(\mathcal{Y}^{\lambda})^{\ell\text{-ss}} \ar@<-0.3ex>@{^{(}->}[d]\ar@{}[rd]|\square & \widetilde{\mathcal{Y}} \ar[l]_-{q'} \ar[r]^-{p'} \ar@<-0.3ex>@{^{(}->}[d] \ar@{}[rd]|\square & \mathcal{Y}^{\ell\text{-ss}} \ar@<-0.3ex>@{^{(}->}[d] \\
\mathcal{Y}^{\lambda} & \ar[l]_-{q} \mathcal{Y}^{\lambda \geqslant 0} \ar[r]^-{p} & \mathcal{Y}
    }
\end{align}
where both squares are Cartesian. 
Then to show the vanishing (\ref{vanish:Mres}), it is enough to show the vanishing 
\begin{align}\label{vanish:Mres2}
    \operatorname{Hom}(p'^{*}E, q'^{*}P|_{(\mathcal{Y}^{\lambda})^{\ell\text{-ss}}})=0, \ 
    E\in \operatorname{M}(\mathcal{Y}^{\ell\text{-ss}})_{\delta}.
\end{align}

Let $\mathcal{Y}^{\ell\text{-ss}}\to Y^{\ell\text{-ss}}$ be the good moduli space.
As in the proof of~\cite[Proposition~3.22]{PTquiver}, it is enough to show the 
vanishing (\ref{vanish:Mres2}) formally locally on $Y^{\ell\text{-ss}}$.
Let $p \in Y^{\ell\text{-ss}}$, and use the same symbol $p$ to denote the unique 
close point in the fiber of $\mathcal{Y}^{\ell\text{-ss}}\to Y^{\ell\text{-ss}}$ at $p$. 
Formally locally at $p\in Y^{\ell\text{-ss}}$, the top horizontal diagram of (\ref{dia:semistable}) is of the form 
\begin{align*}
    A^{\lambda}/G_p^{\lambda} \leftarrow A^{\lambda \geqslant 0}/G_p^{\lambda \geqslant 0} \to 
    A/G_p
\end{align*}
where $A$ is a smooth affine scheme (of finite type over a complete local ring) with
a $G_p=\mathrm{Aut}(p)$-action, see~\cite[Lemma~3.29]{PTquiver}.
Then the vanishing (\ref{vanish:Mres}) on $A/G_p$ follows by comparing the $\lambda$-weights
of $p'^{*}E$ and $q'^{*}P|_{(\mathcal{Y}^{\lambda})^{\ell\text{-ss}}}$
on $A^{\lambda \geqslant 0}/G_p^{\lambda\geqslant 0}$ using the inequality (\ref{ineq:chi''}), 
see the last part of the proof of~\cite[Proposition~3.22]{PTquiver}.

\label{lem:magicgen}
    For $\ell\in M_{0, \mathbb{R}}$ and $\delta \in M(T)_{\mathbb{R}}^W$ with 
    $T'$-weight $w$, the category $\operatorname{Coh}(\mathcal{Y}^{\ell\text{-ss}})_w$ is generated by 
    $j^*(\operatorname{M}(\mathcal{Y})_{\delta})$ and objects of the form $m_{\lambda}(P)$
    where $P \in \operatorname{Coh}(\mathcal{Y}^{\lambda})_w$ is generated by $V_{G^{\lambda}}(\chi'')\otimes \mathcal{O}_{\mathcal{Y}^{\lambda}}$ such that 
    \begin{align}\label{ineq:chi''}
        \langle \lambda, \chi'' \rangle <-\frac{1}{2}\langle \lambda, \mathbb{L}_{\mathcal{Y}}^{\lambda>0}\rangle+\langle \lambda, \delta\rangle
    \end{align}
    and $\lambda \in \{\lambda_1, \ldots, \lambda_m\}$ such that $\langle \lambda, \ell \rangle=0$. Here $V_{G^{\lambda}}(\chi'')$ is the irreducible $G^{\lambda}$-representation with highest weight $\chi''$. The functor $m_{\lambda}$ is 
    the categorical Hall product $m_{\lambda}=p_{*}q^{*}$ for the diagram 
    \begin{align*}
        \mathcal{Y}^{\lambda} \stackrel{q}{\leftarrow} \mathcal{Y}^{\lambda \geqslant 0} \stackrel{p}{\to} \mathcal{Y}.
    \end{align*}

    We may assume that $\lambda_i$ is anti-dominant. 
    Let $\mathbf{W} \subset M(T)_{\mathbb{R}}$ be the polytope defined in (\ref{poly:W}). 
    Let $\chi \in M(T)$ be a dominant weight such that $\chi+\rho-\delta \in \mathbf{W}$.
    By Proposition~\ref{prop:QB:weight}, it is enough to show that 
    \begin{align*}
        \beta_{m_i}\overline{p}_i^{*}(V_G(\chi)\otimes \mathcal{O}_{\mathcal{Y}})\in 
        \operatorname{M}(\overline{\mathcal{Z}_i})_{\delta_i}.
    \end{align*}
    Let $F(\lambda_i) \subset \mathbf{W}$ be a face determined by $\lambda_i$, given by the equation \[\langle \lambda_i, -\rangle=-\frac{1}{2}\langle \lambda_i, Y^{\lambda_i>0}\rangle.\] 
    If $\chi+\rho-\delta \notin F(\lambda_i)$, then we have 
    \begin{align*}
        \beta_{m_i}\overline{p}_i^{*}(V_G(\chi)\otimes \mathcal{O}_{\mathcal{Y}})=0.
    \end{align*}
    If $\chi+\rho-\delta_i \in F(\lambda_i)$, then we can write 
    \begin{align*}
        \chi+\rho-\delta=-\frac{1}{2}Y^{\lambda_i>0}+\psi+\rho^{\lambda_i}
    \end{align*}
    where 
 $\psi \in \mathbf{W}^{\lambda_i} \subset M(T)_{\mathbb{R}}$ is half the Minkowski sum of 
 $T$-weights of $Y^{\lambda_i}$, 
    $\rho^{\lambda_i}$ is half the sum of positive roots of $G^{\lambda_i}$, 
    see the argument of~\cite[Corollary~3.4]{P}. 

    The above equality can be written as 
    \begin{align*}
        \chi=-\frac{1}{2}(Y^{\lambda_i>0}-\mathfrak{g}^{\lambda_i>0})+\psi+\delta=\psi+\delta_i.
    \end{align*}
    Then we have 
    \begin{align*}
        \beta_{m_i}\overline{p}_i^{*}(V_G(\chi)\otimes \mathcal{O}_{\mathcal{Y}})
        =V_{G^{\lambda_i}}(\chi)\otimes \mathcal{O}_{\overline{\mathcal{Z}}_i}
        \in 
        \operatorname{M}(\overline{\mathcal{Z}}_i)_{\delta_i}
\end{align*}

It is enough to consider the case $k=2$. 
Note that we have 
\begin{align*}
    \mathrm{Higgs}_{\operatorname{GL}_{r_1}}(\chi_1)^{\mathrm{ss}}\times \mathrm{Higgs}_{\operatorname{GL}_{r_2}}(\chi_2)^{\mathrm{ss}}
    =\mathrm{Higgs}_{G}(\chi)^{\mathrm{ss}}.
\end{align*}
Since 
$\mathrm{Higgs}_{\operatorname{GL}_r}(\chi)^{\mathrm{ss}}$ is QCA, using (\ref{indtensor}) we have an equivalence
\begin{align}\label{tensor:Higgs}
\operatorname{Coh}(\mathrm{Higgs}_{\operatorname{GL}_{r_1}}(\chi_1)^{\mathrm{ss}})_{w_1}\otimes 
\operatorname{Coh}(\mathrm{Higgs}_{\operatorname{GL}_{r_2}}(\chi_2)^{\mathrm{ss}})_{w_2} \stackrel{\sim}{\to}
\operatorname{Coh}(\mathrm{Higgs}_{G}(\chi)^{\mathrm{ss}})_w.
\end{align}
By Theorem~\ref{thm:PThiggs},
we have semiorthogonal decompositions 
\begin{align*}
    \operatorname{Coh}(\mathrm{Higgs}_{\operatorname{GL}_{r_i}}(\chi_i)^{\mathrm{ss}})_{w_i}
    =\left\langle \bigotimes_{j=1}^{k}\mathbb{T}_{\operatorname{GL}_{r_{ij}}}(\chi_{ij})_{w_{ij}} \right\rangle
\end{align*}
where the right-hand side is after partitions of $(r_i, \chi_i, w_i)$
with $\chi_{ij}/r_{ij}=\chi_i/r_i$ and $w_{i1}/r_{i1}<\cdots<w_{ik}/r_{ik}$.
It follows that the left-hand side of (\ref{tensor:Higgs})
has a semiorthogonal decomposition 
\begin{align}\label{sod:left}
\left\langle 
\bigotimes_{j=1}^{k_1}\mathbb{T}_{\operatorname{GL}_{r_{1j}}}(\chi_{1j})_{w_{1j}} \otimes
\bigotimes_{j'=1}^{k_2}\mathbb{T}_{\operatorname{GL}_{r_{2j'}}}(\chi_{2j'})_{w_{2j'}}
\right\rangle
\end{align}
where $(r_{1j}, \chi_{1j}, w_{1j})$, $(r_{2j'}, \chi_{2j'}, w_{2j'})$ are as above. 

On the other hand, an analogue of the proof of Theorem~\ref{thm:PThiggs}
for $\operatorname{GL}_r$ easily implies it for $\operatorname{GL}_{r_1}\times \operatorname{GL}_{r_2}$. 
Therefore the right-hand side of (\ref{tensor:Higgs})
has a semiorthogonal decomposition 
\begin{align}\label{sod:right}
    \left\langle \bigotimes_{1\leqslant j\leqslant k_1, 1\leqslant j'\leqslant k_2}
    \mathbb{T}_{\operatorname{GL}_{r_{1j}}\times \operatorname{GL}_{r_{2j'}}}(\chi_{1j}+\chi_{2j'})_{w_{1j}+w_{2j'}}\right\rangle
\end{align}
where $(r_{1j}, \chi_{1j}, w_{1j})$, $(r_{2j'}, \chi_{2j'}, w_{2j'})$ are as above. 
The equivalence (\ref{tensor:Higgs}) is compatible with Hall product, so together with the 
definition of limit categories it restricts to the fully-faithful 
functor 
\begin{align}\notag
    \bigotimes_{j=1}^{k_1}\mathbb{T}_{\operatorname{GL}_{r_{1j}}}(\chi_{1j})_{w_{1j}} &\otimes
\bigotimes_{j'=1}^{k_2}\mathbb{T}_{\operatorname{GL}_{r_{2j'}}}(\chi_{2j'})_{w_{2j'}} \\
\label{FF:T}&\hookrightarrow \bigotimes_{1\leqslant j\leqslant k_1, 1\leqslant j'\leqslant k_2}\mathbb{T}_{\operatorname{GL}_{r_{1j}}\times \operatorname{GL}_{r_{2j'}}}(\chi_{1j}+\chi_{2j'})_{w_{1j}+w_{2j'}}.
\end{align}
By comparing the semiorthogonal decompositions (\ref{sod:left}), (\ref{sod:right}) under the 
equivalence (\ref{tensor:Higgs}), we conclude that the functor (\ref{FF:T}) is an equivalence. In particular, 
we have an equivalence (\ref{equiv:Ttensor}).

By Lemma~\ref{lem:dtr}, there is an exact sequence of $G_E$-representations 
\begin{align}\label{exact:ad}
    0 \to \mathbb{T}^0_{(E_G, \phi_G)} \to \mathbb{T}^0_{(E_G, \phi_G^{L})} \to \Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)
    \to \mathbb{T}^1_{(E_G, \phi_G)} \to 0. 
\end{align}
Let $W$ be the cokernel of $\mathbb{T}^0_{(E_G, \phi_G)} \to \mathbb{T}^0_{(E_G, \phi_G^{L})}$. 
By noting that \[(\mathbb{T}^{1}_{(E_G, \phi_G)})^{\vee}\cong \mathbb{T}^{-1}_{(E_G, \phi_G)},\]
we have an isomorphism of $G_E$-representations
\begin{align}\label{rep:V}
    \mathbf{V}\cong \mathbb{T}^0_{(E_G, \phi_G)} \oplus W \oplus W^{\vee} \oplus \mathbb{T}^{-1}_{(E_G, \phi_G)}. 
\end{align}

It follows that 
\begin{align}\label{rep:V2}
      \mathbf{V}_0 \cong \mathbb{T}^0_{(E_G, \phi_G)} \oplus W \oplus W^{\vee} \oplus
      \mathbb{T}^{-1}_{(E_M, \phi_M)}.   
\end{align}
The $G_E$-representation $\mathbb{T}^0_{(E_G, \phi_G)}$ is self-dual by the Serre duality, 
and the last factor $\mathbb{T}^{-1}_{(E_M, \phi_M)}$ is also self-dual since it is the Lie algebra 
of the reductive group $G_E$. Therefore $\mathbf{V}_0$ is self-dual.

\label{lem:cart0}
In the diagram (\ref{dia:WG}), all the bottom squares are derived 
Cartesians and the top left arrow is an isomorphism.

As for the first statement, it is enough to show that the left bottom square is derived Cartesian. 
Let $(E_P, \phi_P)=(E_M, \phi_M)\times^M P$.
Since we have 
\begin{align}\label{T:quot}\mathbb{T}^{-1}_{(E_G, \phi_G)}/\mathbb{T}^{-1}_{(E_M, \phi_M)}
=\mathbb{T}^{-1}_{(E_P, \phi_P)}/\mathbb{T}^{-1}_{(E_M, \phi_M)}
\end{align}
it has positive $\lambda$-weights. Therefore we have 
\begin{align*}
    (\mathbb{T}^{-1}_{(E_G, \phi_G)})^{\lambda \geqslant 0}=
     (\mathbb{T}^{-1}_{(E_M, \phi_M)})^{\lambda \geqslant 0}
     \oplus \left(\mathbb{T}^{-1}_{(E_G, \phi_G)}/\mathbb{T}^{-1}_{(E_M, \phi_M)}\right).
\end{align*}

It follows that 
\begin{align*}
    &\mathbf{V}=\mathbf{V}_0 \oplus \left(\mathbb{T}^{-1}_{(E_P, \phi_P)}/\mathbb{T}^{-1}_{(E_M, \phi_M)}\right), \\ \notag
        &\mathbf{V}^{\lambda \geqslant 0}=\mathbf{V}_0^{\lambda \geqslant 0} \oplus \left(\mathbb{T}^{-1}_{(E_P, \phi_P)}/\mathbb{T}^{-1}_{(E_M, \phi_M)}\right).
\end{align*}
By (\ref{rep:V}) and (\ref{rep:V2}), the left bottom square in (\ref{dia:WG}) is 
derived Cartesian. 
The top left arrow in (\ref{lem:dtr}) is an isomorphism since (\ref{T:quot}) has positive $\lambda$-weights.

Let $\nu \colon B\mathbb{G}_m \to \mathcal{Z}$ be a map 
such that $\nu(0)\in \mathcal{Z}$ corresponds to 
a polystable $M$-Higgs bundle $(E_M, \phi_M)$ as in (\ref{deg:E}). 
We set
\begin{align*}(E_G, \phi_G)=(E_M, \phi_M)\times^M G, \ (E_G, \phi_G^{L})=\iota_D(E_G, \phi_G).
\end{align*}
Let $\lambda \colon \mathbb{G}_m \to \mathrm{Aut}(E_M, \phi_M)$ 
be the one-parameter subgroup as in (\ref{lambda:E}). 
We have the identities in $K(B\mathbb{G}_m)$
\begin{align*}
    &\nu^* \mathbb{L}_{\mathcal{U}^L}=(\mathbb{T}_{\mathrm{Higgs}_G^{L}}|_{(E_G, \phi_G^{L})})^{\vee}, \\
    &\nu^* N_{\mathcal{S}_{\mathcal{V}}/(\mathcal{V}^L)^{\vee}}=(\mathbb{T}^0_{(E_G, \phi_G^{L})} -\mathbb{T}^{-1}_{(E_G, \phi_G^{L})}
    +\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)^{\vee})^{\lambda<0}, \\
    &\nu^* \mathbb{L}_{\mathcal{Z}^L}=(\mathbb{T}_{\mathrm{Higgs}_G^{L}}|_{(E_G, \phi_G^{L})})^{\lambda\vee}, \\
    &\nu^* \mathcal{V}^L|_{\mathcal{Z}}^{>0}=\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)^{\lambda>0}.
\end{align*}

It follows that $2c_1(\nu^*(\delta'' \otimes \delta^{-1}))$ is calculated as 
\begin{align*}
    &c_1\left((\mathbb{T}_{\mathrm{Higgs}_G^{L}}|_{(E_G, \phi_G^{L})})^{\vee}
    +(\mathbb{T}^0_{(E_G, \phi_G^{L})})^{\lambda<0} -(\mathbb{T}^{-1}_{(E_G, \phi_G^{L})})^{\lambda<0} \right. \\
    &\quad \quad\left.+(\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)^{\vee})^{\lambda<0} -(\mathbb{T}_{\mathrm{Higgs}_G^{L}}|_{(E_G, \phi_G^{L})})^{\lambda\vee}+2\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)^{\lambda>0} \right) \\
    &=c_1\left(-\mathbb{T}^0_{(E_G, \phi_G^{L})}+\mathbb{T}^{-1}_{(E_G, \phi_G^{L})}+(\mathbb{T}^0_{(E_G, \phi_G^{L})})^{\lambda<0} 
    -(\mathbb{T}^{-1}_{(E_G, \phi_G^{L})})^{\lambda<0}\right.\\
    &\quad \qquad\left.+(\mathbb{T}^0_{(E_G, \phi_G^{L})})^{\lambda} -(\mathbb{T}^{-1}_{(E_G, \phi_G^{L})})^{\lambda}
    +\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)^{\lambda>0} \right)\\
    &=c_1\left(-(\mathbb{T}^0_{(E_G, \phi_G^{L})})^{\lambda>0}+\Gamma(\mathrm{Ad}_{\mathfrak{g}}(E_G)|_{D}\otimes L)^{\lambda>0}+(\mathbb{T}^{-1}_{(E_G, \phi_G^{L})})^{\lambda>0}\right)
\end{align*}
which equals to $c_1(-\mathbb{T}_{\mathrm{Higgs}_G}|_{(E_G, \phi_G)}^{\lambda>0})$ by Lemma~\ref{lem:dtr}. 
It follows that 
\begin{align*}
    2c_1(\nu^*(\delta''\otimes \delta^{-1}))=c_1((\mathbb{T}_{\mathrm{Higgs}_G}|_{(E_G, \phi_G)})^{\lambda<0})^{\vee})=c_1(\nu^*\mathbb{L}_{p}).
\end{align*}
Therefore the lemma holds.
